1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"time"
13	)
14	
15	// 数据目录布局：
16	//
17	//	<dir>/state.json      全部业务数据（客户、用量、账单、封账状态）
18	//	<dir>/state.json.tmp  原子写入临时文件（保存后 rename 覆盖）
19	//
20	// 所有命令顺序运行，单次调用内完成“读入—修改—整体原子落盘”，
21	// 因此账单与封账状态在同一次保存中持久化，不会出现半写状态。
22	
23	const stateVersion = 1
24	
25	type customer struct {
26		ID     string `json:"id"`
27		Name   string `json:"name"`
28		Price  int64  `json:"price_fen"`         // 固定单价，非负整数分，创建后不可修改
29		PlanID string `json:"plan_id,omitempty"` // 绑定的阶梯计费方案标识；空表示固定单价客户，创建后不可变更
30	}
31	
32	// tier 是阶梯计费方案中的一档：Limit 为月累计数量上限（正整数），
33	// 仅最后一档无上限（Limit 为 0）；Price 为该档每单位价格（非负整数分）。
34	type tier struct {
35		Limit int64 `json:"limit"`     // 累计数量上限；0 表示无上限（仅最后一档）
36		Price int64 `json:"price_fen"` // 每单位价格，非负整数分，可升可降
37	}
38	
39	// plan 是按月累计用量的阶梯计费方案：标识唯一非空、名称非空、固定月费
40	// （非负整数分，省略视为 0）与至少一档有序阶梯；月费与规则创建后不可修改。
41	type plan struct {
42		ID         string `json:"id"`
43		Name       string `json:"name"`
44		MonthlyFee int64  `json:"monthly_fee_fen,omitempty"` // 固定月费，非负整数分；每账期收取一次整月，不按天折算
45		Tiers      []tier `json:"tiers"`                     // 至少一档；有限上限严格递增，最后一档无上限
46	}
47	
48	type usageRecord struct {
49		ID         string `json:"id"`
50		CustomerID string `json:"customer_id"`
51		Time       string `json:"time"` // RFC3339，保留原始输入用于去重判定
52		Quantity   int64  `json:"quantity"`
53	}
54	
55	// lineSegment 是阶梯计费下一条用量记录落入某一档的分段：数量与小计；
56	// 该档单价由账单保存的方案规则按档位序号取得。
57	type lineSegment struct {
58		Tier     int   `json:"tier"`     // 档位序号（0 起，对应账单保存的方案规则）
59		Quantity int64 `json:"quantity"` // 落入本档的数量
60		Fee      int64 `json:"fee_fen"`  // 本分段小计（数量 × 该档单价）
61	}
62	
63	// tierTotal 是阶梯账单中某一档的合计数量与金额（与 PlanTiers 顺序对齐）。
64	type tierTotal struct {
65		Quantity int64 `json:"quantity"`
66		Fee      int64 `json:"fee_fen"`
67	}
68	
69	type billLine struct {
70		UsageID  string        `json:"usage_id"`
71		Time     string        `json:"time"`
72		Quantity int64         `json:"quantity"`
73		LineFee  int64         `json:"line_fee_fen"`
74		Segments []lineSegment `json:"segments,omitempty"` // 阶梯账单：本条用量的跨档分段
75	}
76	
77	type bill struct {
78		ID         string      `json:"id"`
79		CustomerID string      `json:"customer_id"`
80		Month      string      `json:"month"`                 // YYYY-MM（UTC）
81		Pricing    string      `json:"pricing,omitempty"`     // 计价类型：空或 fixed 为固定单价；tiered 为阶梯计费
82		PlanID     string      `json:"plan_id,omitempty"`     // 阶梯账单：方案标识
83		PlanName   string      `json:"plan_name,omitempty"`   // 阶梯账单：方案名称（快照）
84		PlanTiers  []tier      `json:"plan_tiers,omitempty"`  // 阶梯账单：完整方案规则（快照）
85		TierTotals []tierTotal `json:"tier_totals,omitempty"` // 阶梯账单：各档实际数量与金额合计
86		// 阶梯账单：实际收取的固定月费快照（分），非负；按账期有效方案收取一次
87		// 整月，不计入总数量、各档金额或逐条小计。固定单价账单恒为 0。
88		MonthlyFee int64      `json:"monthly_fee_fen,omitempty"`
89		TotalQty   int64      `json:"total_quantity"`
90		UnitPrice  int64      `json:"unit_price_fen"` // 固定单价账单的单价；阶梯账单恒为 0（不伪造统一单价）
91		TotalFee   int64      `json:"total_fee_fen"`
92		Lines      []billLine `json:"lines"`
93		CreatedAt  string     `json:"created_at"`
94	}
95	
96	// adjustment 是对已结算账单的一次费用调整（正数补收、负数减免）。
97	// 记录一旦写入永不删除；撤销只是追加撤销信息，保留原记录。
98	type adjustment struct {
99		ID           string `json:"id"`
100		CustomerID   string `json:"customer_id"`
101		Month        string `json:"month"` // YYYY-MM（UTC），与所属账单一致
102		Amount       int64  `json:"amount_fen"`
103		Reason       string `json:"reason"`
104		Seq          int64  `json:"seq"` // 全局递增操作序号，决定历史展示顺序
105		CreatedAt    string `json:"created_at"`
106		Revoked      bool   `json:"revoked"`
107		RevokeReason string `json:"revoke_reason,omitempty"`
108		RevokeSeq    int64  `json:"revoke_seq,omitempty"`
109		RevokedAt    string `json:"revoked_at,omitempty"`
110	}
111	
112	// paymentAllocation 是一笔收款在某个已结算月份上的分配（正整数分）。
113	type paymentAllocation struct {
114		Month  string `json:"month"`      // YYYY-MM（UTC），须已有账单
115		Amount int64  `json:"amount_fen"` // 正整数分
116	}
117	
118	// payment 是一笔实收登记：同一客户的一笔汇款（总额 Total 分）按分配列表
119	// 计入一个或多个已结算月份；单账单收款视为只有一项分配的汇款。
120	// 记录一旦写入永不删除；撤销只是追加撤销信息，整笔撤销全部分配并保留
121	// 原记录，撤销后该笔不再计入实收，也不会因重放而恢复。
122	type payment struct {
123		ID           string              `json:"id"`
124		CustomerID   string              `json:"customer_id"`
125		Total        int64               `json:"total_fen"` // 收款总额，正整数分，等于分配合计
126		Note         string              `json:"note"`
127		Allocations  []paymentAllocation `json:"allocations"` // 至少一项，月份不重复，按月份升序保存
128		Seq          int64               `json:"seq"`         // 全局递增操作序号，决定历史展示顺序
129		CreatedAt    string              `json:"created_at"`
130		Revoked      bool                `json:"revoked"`
131		RevokeReason string              `json:"revoke_reason,omitempty"`
132		RevokeSeq    int64               `json:"revoke_seq,omitempty"`
133		RevokedAt    string              `json:"revoked_at,omitempty"`
134	}
135	
136	// UnmarshalJSON 兼容旧版单账单收款格式（month + amount_fen，无 allocations）：
137	// 读入时归一化为一项分配，之后一律按新格式写回。
138	func (p *payment) UnmarshalJSON(data []byte) error {
139		type plain payment // 去掉方法，避免递归
140		var raw struct {
141			plain
142			Month  string `json:"month"`      // 旧格式：所属账单月份
143			Amount int64  `json:"amount_fen"` // 旧格式：收款金额
144		}
145		if err := json.Unmarshal(data, &raw); err != nil {
146			return err
147		}
148		*p = payment(raw.plain)
149		if len(p.Allocations) == 0 && raw.Month != "" {
150			p.Allocations = []paymentAllocation{{Month: raw.Month, Amount: raw.Amount}}
151			p.Total = raw.Amount
152		}
153		return nil
154	}
155	
156	// amountFor 返回该收款在指定月份的分配金额；无分配时为 0。
157	func (p *payment) amountFor(month string) int64 {
158		for _, al := range p.Allocations {
159			if al.Month == month {
160				return al.Amount
161			}
162		}
163		return 0
164	}
165	
166	// correction 是对一笔未撤销收款的分配更正：客户、总额、备注、原账单及
167	// 应付不变，仅把该笔收款当前生效的分配整体替换为完整新分配。记录一旦写入
168	// 永不删除；首次登记内容永久保留，bill pay / bill remit 仍按原始分配判重，
169	// 更正不影响收款身份。可连续更正，每次以当时最新分配为起点。
170	type correction struct {
171		ID          string              `json:"id"`
172		PaymentID   string              `json:"payment_id"` // 目标收款标识
173		Reason      string              `json:"reason"`
174		Allocations []paymentAllocation `json:"allocations"` // 完整新分配，至少一项，月份不重复，按月份升序保存
175		Seq         int64               `json:"seq"`         // 全局递增操作序号，与调整/收款及其撤销共用
176		CreatedAt   string              `json:"created_at"`
177	}
178	
179	// planChange 是阶梯客户的一次按月生效的方案变更：自生效月（UTC 自然月，
180	// 含）起改用目标方案，直到下一次变更；生效月之前的月份不受影响。记录一旦
181	// 写入永不修改或删除；变更不产生账后流水事件，也不占用全局操作序号。
182	type planChange struct {
183		CustomerID string `json:"customer_id"`
184		Month      string `json:"month"`   // YYYY-MM（UTC），生效月（含）
185		PlanID     string `json:"plan_id"` // 目标阶梯计费方案标识
186		Reason     string `json:"reason"`
187		CreatedAt  string `json:"created_at"`
188	}
189	
190	// suspension 是阶梯客户的一段按月暂停区间：自起月（UTC 自然月，含）起
191	// 暂停服务，直到结束月（不含），即 [StartMonth, EndMonth) 覆盖的自然月。
192	// 暂停月不接收用量、不产生月费账单；区间可相接（相接视为连续暂停）但不得
193	// 重叠。记录一旦写入永不修改或删除；暂停不产生账后流水事件，也不占用全局
194	// 操作序号。固定单价客户不适用暂停。
195	type suspension struct {
196		CustomerID string `json:"customer_id"`
197		StartMonth string `json:"start_month"` // YYYY-MM（UTC），暂停起月（含）
198		EndMonth   string `json:"end_month"`   // YYYY-MM（UTC），结束月（不含），严格晚于起月
199		Reason     string `json:"reason"`
200		CreatedAt  string `json:"created_at"`
201	}
202	
203	type state struct {
204		Version     int                     `json:"version"`
205		Customers   map[string]*customer    `json:"customers"`
206		Plans       map[string]*plan        `json:"plans"`                 // 全局唯一方案标识 -> 阶梯计费方案
207		Usage       map[string]*usageRecord `json:"usage"`                 // 全局唯一用量标识 -> 记录
208		Bills       map[string]*bill        `json:"bills"`                 // 客户 + "|" + 月份 -> 账单
209		Adjustments map[string]*adjustment  `json:"adjustments"`           // 全局唯一调整标识 -> 记录
210		Payments    map[string]*payment     `json:"payments"`              // 全局唯一收款标识 -> 记录（与调整标识相互独立，可同名）
211		Corrections map[string]*correction  `json:"corrections"`           // 全局唯一更正标识 -> 记录（与收款、调整标识相互独立，可同名）
212		PlanChanges map[string]*planChange  `json:"plan_changes"`          // 客户 + "|" + 生效月 -> 方案变更（按生效月递增追加，不可改写）
213		Suspensions map[string]*suspension  `json:"suspensions,omitempty"` // 客户 + "|" + 起月 -> 暂停区间（不可改写）
214		NextSeq     int64                   `json:"next_seq"`              // 已分配的最大操作序号（调整/收款/更正及其撤销共用；方案变更与暂停不占用）
215		path        string                  `json:"-"`
216	}
217	
218	// loadStore 读取数据目录；目录不存在时按需创建并视为空库。
219	// 已存在但损坏或不可读取的数据一律报错，绝不当作空库覆盖。
220	func loadStore(dir string) (*state, error) {
221		p := filepath.Join(dir, "state.json")
222		data, err := os.ReadFile(p)
223		if err != nil {
224			if errors.Is(err, os.ErrNotExist) {
225				if mkErr := os.MkdirAll(dir, 0o755); mkErr != nil {
226					return nil, fmt.Errorf("无法创建数据目录 %s: %w", dir, mkErr)
227				}
228				return newState(p), nil
229			}
230			return nil, fmt.Errorf("数据文件不可读取 %s: %w", p, err)
231		}
232	
233		var s state
234		dec := json.NewDecoder(bytes.NewReader(data))
235		if err := dec.Decode(&s); err != nil {
236			return nil, fmt.Errorf("数据文件已损坏（不是有效的 JSON）%s: %w", p, err)
237		}
238		// 拒绝完整 JSON 之后的任何非空白内容（包括单独的 ] 或 }），避免静默
239		// 吞掉异常数据；合法尾随空白仍可读取。
240		if off := dec.InputOffset(); off < int64(len(data)) {
241			if strings.TrimSpace(string(data[off:])) != "" {
242				return nil, fmt.Errorf("数据文件已损坏（JSON 之后存在多余内容）: %s", p)
243			}
244		}
245		if err := s.validate(); err != nil {
246			return nil, fmt.Errorf("数据文件已损坏: %w", err)
247		}
248		// 旧版本数据文件没有 plans/adjustments/payments/corrections/plan_changes/
249		// suspensions/next_seq 字段：视为零方案、零调整、零实收、零更正、
250		// 零方案变更、零暂停。
251		if s.Plans == nil {
252			s.Plans = map[string]*plan{}
253		}
254		if s.Adjustments == nil {
255			s.Adjustments = map[string]*adjustment{}
256		}
257		if s.Payments == nil {
258			s.Payments = map[string]*payment{}
259		}
260		if s.Corrections == nil {
261			s.Corrections = map[string]*correction{}
262		}
263		if s.PlanChanges == nil {
264			s.PlanChanges = map[string]*planChange{}
265		}
266		if s.Suspensions == nil {
267			s.Suspensions = map[string]*suspension{}
268		}
269		s.path = p
270		return &s, nil
271	}
272	
273	func newState(p string) *state {
274		return &state{
275			Version:     stateVersion,
276			Customers:   map[string]*customer{},
277			Plans:       map[string]*plan{},
278			Usage:       map[string]*usageRecord{},
279			Bills:       map[string]*bill{},
280			Adjustments: map[string]*adjustment{},
281			Payments:    map[string]*payment{},
282			Corrections: map[string]*correction{},
283			PlanChanges: map[string]*planChange{},
284			Suspensions: map[string]*suspension{},
285			path:        p,
286		}
287	}
288	
289	// validate 对读入的库做一致性检查，任何异常都按损坏处理。
290	func (s *state) validate() error {
291		if s.Version != stateVersion {
292			return fmt.Errorf("不支持的数据版本 %d（仅支持 %d）", s.Version, stateVersion)
293		}
294		if s.Customers == nil || s.Usage == nil || s.Bills == nil {
295			return errors.New("缺少必要的数据节")
296		}
297		for id, p := range s.Plans {
298			if p == nil {
299				return fmt.Errorf("方案 %q 的数据为空", id)
300			}
301			if p.ID != id {
302				return fmt.Errorf("方案标识不一致: 键 %q / 记录 %q", id, p.ID)
303			}
304			if err := validatePlanRules(p); err != nil {
305				return err
306			}
307		}
308		for id, c := range s.Customers {
309			if c == nil {
310				return fmt.Errorf("客户 %q 的数据为空", id)
311			}
312			if c.ID != id {
313				return fmt.Errorf("客户标识不一致: 键 %q / 记录 %q", id, c.ID)
314			}
315			if c.ID == "" || c.Name == "" {
316				return fmt.Errorf("客户 %q 的标识或名称为空", id)
317			}
318			if c.Price < 0 {
319				return fmt.Errorf("客户 %q 单价为负", id)
320			}
321			if c.PlanID != "" {
322				if _, ok := s.Plans[c.PlanID]; !ok {
323					return fmt.Errorf("客户 %q 绑定了不存在的方案 %q", id, c.PlanID)
324				}
325			}
326		}
327		// 方案变更：键、客户（须为绑定阶梯方案的客户）、目标方案、生效月与
328		// 原因都必须自洽；同一客户的变更生效月由键保证唯一。
329		for key, ch := range s.PlanChanges {
330			if ch == nil {
331				return fmt.Errorf("方案变更 %q 的数据为空", key)
332			}
333			if planChangeKey(ch.CustomerID, ch.Month) != key {
334				return fmt.Errorf("方案变更键不一致: 键 %q / 客户月份 %s|%s", key, ch.CustomerID, ch.Month)
335			}
336			c, ok := s.Customers[ch.CustomerID]
337			if !ok {
338				return fmt.Errorf("方案变更 %q 引用了不存在的客户 %q", key, ch.CustomerID)
339			}
340			if c.PlanID == "" {
341				return fmt.Errorf("方案变更 %q 的客户 %q 未绑定阶梯方案", key, ch.CustomerID)
342			}
343			if !validMonth(ch.Month) {
344				return fmt.Errorf("方案变更 %q 的生效月无效", key)
345			}
346			if _, ok := s.Plans[ch.PlanID]; !ok {
347				return fmt.Errorf("方案变更 %q 引用了不存在的方案 %q", key, ch.PlanID)
348			}
349			if strings.TrimSpace(ch.Reason) == "" {
350				return fmt.Errorf("方案变更 %q 的原因为空", key)
351			}
352		}
353		for id, u := range s.Usage {
354			if u == nil {
355				return fmt.Errorf("用量 %q 的数据为空", id)
356			}
357			if u.ID != id {
358				return fmt.Errorf("用量标识不一致: 键 %q / 记录 %q", id, u.ID)
359			}
360			if u.ID == "" {
361				return errors.New("存在空的用量标识")
362			}
363			if _, ok := s.Customers[u.CustomerID]; !ok {
364				return fmt.Errorf("用量 %q 引用了不存在的客户 %q", u.ID, u.CustomerID)
365			}
366			if u.Quantity <= 0 {
367				return fmt.Errorf("用量 %q 的数量非正", u.ID)
368			}
369			if _, err := time.Parse(time.RFC3339, u.Time); err != nil {
370				return fmt.Errorf("用量 %q 的时间不是 RFC3339: %w", u.ID, err)
371			}
372		}
373		for key, b := range s.Bills {
374			if b == nil {
375				return fmt.Errorf("账单 %q 的数据为空", key)
376			}
377			if billKey(b.CustomerID, b.Month) != key {
378				return fmt.Errorf("账单键不一致: 键 %q / 客户月份 %s|%s", key, b.CustomerID, b.Month)
379			}
380			if _, ok := s.Customers[b.CustomerID]; !ok {
381				return fmt.Errorf("账单 %q 引用了不存在的客户 %q", key, b.CustomerID)
382			}
383			if !validMonth(b.Month) {
384				return fmt.Errorf("账单 %q 的月份无效", key)
385			}
386			if b.MonthlyFee < 0 {
387				return fmt.Errorf("账单 %q 的月费为负", key)
388			}
389			// 仅月费大于 0 的账单允许空用量明细（无用量也须出账收取月费）。
390			if len(b.Lines) == 0 && b.MonthlyFee == 0 {
391				return fmt.Errorf("账单 %q 没有明细", key)
392			}
393			var qty, fee int64
394			for _, ln := range b.Lines {
395				u, ok := s.Usage[ln.UsageID]
396				if !ok {
397					return fmt.Errorf("账单 %q 引用了不存在的用量 %q", key, ln.UsageID)
398				}
399				if u.CustomerID != b.CustomerID || u.Time != ln.Time || u.Quantity != ln.Quantity {
400					return fmt.Errorf("账单 %q 的明细 %q 与用量记录不一致", key, ln.UsageID)
401				}
402				if !inMonth(u.Time, b.Month) {
403					return fmt.Errorf("账单 %q 的明细 %q 不在账期内", key, ln.UsageID)
404				}
405				var err error
406				qty, err = add64(qty, ln.Quantity)
407				if err != nil {
408					return fmt.Errorf("账单 %q 汇总数量溢出", key)
409				}
410				fee, err = add64(fee, ln.LineFee)
411				if err != nil {
412					return fmt.Errorf("账单 %q 汇总金额溢出", key)
413				}
414			}
415			if qty != b.TotalQty {
416				return fmt.Errorf("账单 %q 总数量与明细不符", key)
417			}
418			// 原总金额 = 月费 + 全月用量费；月费不计入逐条用量小计，故明细
419			// 小计之和等于用量费（总金额 − 月费）。月费与总金额均非负，相减
420			// 不会溢出；总金额为负或小于月费时此处必然不符。
421			if usageFee := b.TotalFee - b.MonthlyFee; fee != usageFee {
422				return fmt.Errorf("账单 %q 总金额不等于月费加全月用量费（明细小计合计 %d 分，月费 %d 分，总金额 %d 分）",
423					key, fee, b.MonthlyFee, b.TotalFee)
424			}
425			c := s.Customers[b.CustomerID]
426			switch b.Pricing {
427			case "", "fixed":
428				// 固定单价账单：每条小计必须等于 数量×客户固定单价，且不得
429				// 携带阶梯方案信息、分段或月费。
430				if b.PlanID != "" || b.PlanName != "" || len(b.PlanTiers) > 0 || len(b.TierTotals) > 0 {
431					return fmt.Errorf("账单 %q 是固定单价账单但携带阶梯方案信息", key)
432				}
433				if b.MonthlyFee != 0 {
434					return fmt.Errorf("账单 %q 是固定单价账单但携带月费", key)
435				}
436				for _, ln := range b.Lines {
437					if len(ln.Segments) > 0 {
438						return fmt.Errorf("账单 %q 的明细 %q 携带阶梯分段", key, ln.UsageID)
439					}
440					lf, err := mul64(ln.Quantity, c.Price)
441					if err != nil {
442						return fmt.Errorf("账单 %q 明细 %q 小计溢出", key, ln.UsageID)
443					}
444					if lf != ln.LineFee {
445						return fmt.Errorf("账单 %q 明细 %q 小计与数量×单价不符", key, ln.UsageID)
446					}
447				}
448				if b.UnitPrice != c.Price {
449					return fmt.Errorf("账单 %q 单价与客户固定单价不符", key)
450				}
451			case "tiered":
452				if err := s.validateTieredBill(key, b, c); err != nil {
453					return err
454				}
455			default:
456				return fmt.Errorf("账单 %q 的计价类型 %q 未知", key, b.Pricing)
457			}
458			// 封账期内不得存在游离于账单之外的用量（封账后新增被禁止，
459			// 而已入账记录理应全部在明细中）。
460			for _, u := range s.Usage {
461				if u.CustomerID == b.CustomerID && inMonth(u.Time, b.Month) {
462					found := false
463					for _, ln := range b.Lines {
464						if ln.UsageID == u.ID {
465							found = true
466							break
467						}
468					}
469					if !found {
470						return fmt.Errorf("客户 %s 的 %s 已封账，但用量 %q 未计入账单", b.CustomerID, b.Month, u.ID)
471					}
472				}
473			}
474		}
475	
476		// 暂停区间：键、客户（须为绑定阶梯方案的客户）、区间与原因都必须自洽；
477		// 同一客户的区间不得重叠（可以相接）；暂停月内不得存在用量或账单。
478		// 旧文件缺少暂停记录视为正常服务（Suspensions 已在载入时补为空表）。
479		for key, su := range s.Suspensions {
480			if su == nil {
481				return fmt.Errorf("暂停区间 %q 的数据为空", key)
482			}
483			if suspensionKey(su.CustomerID, su.StartMonth) != key {
484				return fmt.Errorf("暂停区间键不一致: 键 %q / 客户起月 %s|%s", key, su.CustomerID, su.StartMonth)
485			}
486			c, ok := s.Customers[su.CustomerID]
487			if !ok {
488				return fmt.Errorf("暂停区间 %q 引用了不存在的客户 %q", key, su.CustomerID)
489			}
490			if c.PlanID == "" {
491				return fmt.Errorf("暂停区间 %q 的客户 %q 未绑定阶梯方案（固定单价客户不适用暂停）", key, su.CustomerID)
492			}
493			if !validMonth(su.StartMonth) {
494				return fmt.Errorf("暂停区间 %q 的起月无效", key)
495			}
496			if !validMonth(su.EndMonth) || su.EndMonth <= su.StartMonth {
497				return fmt.Errorf("暂停区间 %q 的结束月无效（结束月必须是晚于起月 %s 的 YYYY-MM）", key, su.StartMonth)
498			}
499			if strings.TrimSpace(su.Reason) == "" {
500				return fmt.Errorf("暂停区间 %q 的原因为空", key)
501			}
502		}
503		for customerID := range s.Customers {
504			list := s.suspensionsFor(customerID)
505			for i := 1; i < len(list); i++ {
506				if list[i].StartMonth < list[i-1].EndMonth {
507					return fmt.Errorf("客户 %s 的暂停区间 %s..%s 与 %s..%s 重叠（区间可以相接但不得重叠）",
508						customerID, list[i-1].StartMonth, list[i-1].EndMonth, list[i].StartMonth, list[i].EndMonth)
509				}
510			}
511			for _, su := range list {
512				for _, u := range s.Usage {
513					if u.CustomerID == customerID && monthInRange(utcMonth(u.Time), su.StartMonth, su.EndMonth) {
514						return fmt.Errorf("客户 %s 在暂停区间 %s..%s（不含结束月）内存在用量 %q（%s）",
515							customerID, su.StartMonth, su.EndMonth, u.ID, utcMonth(u.Time))
516					}
517				}
518				for _, b := range s.Bills {
519					if b.CustomerID == customerID && monthInRange(b.Month, su.StartMonth, su.EndMonth) {
520						return fmt.Errorf("客户 %s 在暂停区间 %s..%s（不含结束月）内存在账单（月份 %s），暂停月不得封账",
521							customerID, su.StartMonth, su.EndMonth, b.Month)
522					}
523				}
524			}
525		}
526	
527		// 调整与收款记录：标识、内容、引用与序号都必须自洽。
528		// 调整与收款共用同一个全局操作序号池；两者标识命名空间相互独立，
529		// 允许同名，各自判重与撤销。
530		if s.NextSeq < 0 {
531			return fmt.Errorf("操作序号计数器为负: %d", s.NextSeq)
532		}
533		seenSeq := make(map[int64]string) // 全局操作序号（登记与撤销共用同一池）-> 来源描述
534		for id, a := range s.Adjustments {
535			if a == nil {
536				return fmt.Errorf("调整 %q 的数据为空", id)
537			}
538			if a.ID != id {
539				return fmt.Errorf("调整标识不一致: 键 %q / 记录 %q", id, a.ID)
540			}
541			if a.ID == "" {
542				return errors.New("存在空的调整标识")
543			}
544			if a.Amount == 0 {
545				return fmt.Errorf("调整 %q 的金额为零", id)
546			}
547			if strings.TrimSpace(a.Reason) == "" {
548				return fmt.Errorf("调整 %q 的原因为空", id)
549			}
550			if !validMonth(a.Month) {
551				return fmt.Errorf("调整 %q 的月份无效", id)
552			}
553			if _, ok := s.Customers[a.CustomerID]; !ok {
554				return fmt.Errorf("调整 %q 引用了不存在的客户 %q", id, a.CustomerID)
555			}
556			if _, ok := s.Bills[billKey(a.CustomerID, a.Month)]; !ok {
557				return fmt.Errorf("调整 %q 引用了不存在的账单（客户 %s 月份 %s）", id, a.CustomerID, a.Month)
558			}
559			if a.Seq < 1 || a.Seq > s.NextSeq {
560				return fmt.Errorf("调整 %q 的操作序号越界", id)
561			}
562			if prev, dup := seenSeq[a.Seq]; dup {
563				return fmt.Errorf("调整 %q 与 %q 的操作序号重复", id, prev)
564			}
565			seenSeq[a.Seq] = "调整 " + id
566			if a.Revoked {
567				if strings.TrimSpace(a.RevokeReason) == "" {
568					return fmt.Errorf("调整 %q 已撤销但撤销原因为空", id)
569				}
570				if a.RevokeSeq <= a.Seq || a.RevokeSeq > s.NextSeq {
571					return fmt.Errorf("调整 %q 的撤销序号越界", id)
572				}
573				if prev, dup := seenSeq[a.RevokeSeq]; dup {
574					return fmt.Errorf("撤销调整 %q 与 %q 的操作序号重复", id, prev)
575				}
576				seenSeq[a.RevokeSeq] = "撤销调整 " + id
577			} else if a.RevokeReason != "" || a.RevokeSeq != 0 {
578				return fmt.Errorf("调整 %q 未撤销但存在撤销信息", id)
579			}
580		}
581		for id, p := range s.Payments {
582			if p == nil {
583				return fmt.Errorf("收款 %q 的数据为空", id)
584			}
585			if p.ID != id {
586				return fmt.Errorf("收款标识不一致: 键 %q / 记录 %q", id, p.ID)
587			}
588			if p.ID == "" {
589				return errors.New("存在空的收款标识")
590			}
591			if p.Total <= 0 {
592				return fmt.Errorf("收款 %q 的总额不是正整数", id)
593			}
594			if strings.TrimSpace(p.Note) == "" {
595				return fmt.Errorf("收款 %q 的备注为空", id)
596			}
597			if _, ok := s.Customers[p.CustomerID]; !ok {
598				return fmt.Errorf("收款 %q 引用了不存在的客户 %q", id, p.CustomerID)
599			}
600			if len(p.Allocations) == 0 {
601				return fmt.Errorf("收款 %q 没有分配", id)
602			}
603			seenMonths := make(map[string]bool)
604			var sum int64
605			for _, al := range p.Allocations {
606				if !validMonth(al.Month) {
607					return fmt.Errorf("收款 %q 的分配月份 %q 无效", id, al.Month)
608				}
609				if seenMonths[al.Month] {
610					return fmt.Errorf("收款 %q 的分配月份 %s 重复", id, al.Month)
611				}
612				seenMonths[al.Month] = true
613				if al.Amount <= 0 {
614					return fmt.Errorf("收款 %q 在 %s 的分配金额不是正整数", id, al.Month)
615				}
616				if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
617					return fmt.Errorf("收款 %q 的分配引用了不存在的账单（客户 %s 月份 %s）", id, p.CustomerID, al.Month)
618				}
619				var err error
620				sum, err = add64(sum, al.Amount)
621				if err != nil {
622					return fmt.Errorf("收款 %q 的分配金额汇总溢出: %w", id, err)
623				}
624			}
625			if sum != p.Total {
626				return fmt.Errorf("收款 %q 的分配合计 %d 分与总额 %d 分不一致", id, sum, p.Total)
627			}
628			if p.Seq < 1 || p.Seq > s.NextSeq {
629				return fmt.Errorf("收款 %q 的操作序号越界", id)
630			}
631			if prev, dup := seenSeq[p.Seq]; dup {
632				return fmt.Errorf("收款 %q 与 %q 的操作序号重复", id, prev)
633			}
634			seenSeq[p.Seq] = "收款 " + id
635			if p.Revoked {
636				if strings.TrimSpace(p.RevokeReason) == "" {
637					return fmt.Errorf("收款 %q 已撤销但撤销原因为空", id)
638				}
639				if p.RevokeSeq <= p.Seq || p.RevokeSeq > s.NextSeq {
640					return fmt.Errorf("收款 %q 的撤销序号越界", id)
641				}
642				if prev, dup := seenSeq[p.RevokeSeq]; dup {
643					return fmt.Errorf("撤销收款 %q 与 %q 的操作序号重复", id, prev)
644				}
645				seenSeq[p.RevokeSeq] = "撤销收款 " + id
646			} else if p.RevokeReason != "" || p.RevokeSeq != 0 {
647				return fmt.Errorf("收款 %q 未撤销但存在撤销信息", id)
648			}
649		}
650		// 分配更正记录：标识、目标收款、原因、新分配与序号都必须自洽。
651		// 更正标识与收款、调整标识命名空间相互独立，允许同名。
652		for id, c := range s.Corrections {
653			if c == nil {
654				return fmt.Errorf("更正 %q 的数据为空", id)
655			}
656			if c.ID != id {
657				return fmt.Errorf("更正标识不一致: 键 %q / 记录 %q", id, c.ID)
658			}
659			if c.ID == "" {
660				return errors.New("存在空的更正标识")
661			}
662			p, ok := s.Payments[c.PaymentID]
663			if !ok {
664				return fmt.Errorf("更正 %q 引用了不存在的收款 %q", id, c.PaymentID)
665			}
666			if strings.TrimSpace(c.Reason) == "" {
667				return fmt.Errorf("更正 %q 的原因为空", id)
668			}
669			if len(c.Allocations) == 0 {
670				return fmt.Errorf("更正 %q 没有新分配", id)
671			}
672			seenMonths := make(map[string]bool)
673			var sum int64
674			for _, al := range c.Allocations {
675				if !validMonth(al.Month) {
676					return fmt.Errorf("更正 %q 的分配月份 %q 无效", id, al.Month)
677				}
678				if seenMonths[al.Month] {
679					return fmt.Errorf("更正 %q 的分配月份 %s 重复", id, al.Month)
680				}
681				seenMonths[al.Month] = true
682				if al.Amount <= 0 {
683					return fmt.Errorf("更正 %q 在 %s 的分配金额不是正整数", id, al.Month)
684				}
685				if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
686					return fmt.Errorf("更正 %q 的分配引用了不存在的账单（客户 %s 月份 %s）", id, p.CustomerID, al.Month)
687				}
688				var err error
689				sum, err = add64(sum, al.Amount)
690				if err != nil {
691					return fmt.Errorf("更正 %q 的分配金额汇总溢出: %w", id, err)
692				}
693			}
694			if sum != p.Total {
695				return fmt.Errorf("更正 %q 的分配合计 %d 分与关联收款 %q 的总额 %d 分不一致", id, sum, c.PaymentID, p.Total)
696			}
697			if c.Seq <= p.Seq || c.Seq > s.NextSeq {
698				return fmt.Errorf("更正 %q 的操作序号越界", id)
699			}
700			if p.Revoked && c.Seq > p.RevokeSeq {
701				return fmt.Errorf("更正 %q 的操作序号晚于关联收款 %q 的撤销序号", id, c.PaymentID)
702			}
703			if prev, dup := seenSeq[c.Seq]; dup {
704				return fmt.Errorf("更正 %q 与 %q 的操作序号重复", id, prev)
705			}
706			seenSeq[c.Seq] = "更正 " + id
707		}
708		// 每张账单：当前应付（原总金额 + 全部未撤销调整净额）必须介于
709		// 0 与有符号 64 位最大值之间；实收（全部未撤销收款按最新分配在该月
710		// 计入之和）必须满足 0 ≤ 实收 ≤ 当前应付。越界说明金额与记录不一致。
711		for key, b := range s.Bills {
712			_, payable, err := billTotals(b, adjustmentsFor(s, b.CustomerID, b.Month))
713			if err != nil {
714				return fmt.Errorf("账单 %q 的调整金额与记录不一致: %w", key, err)
715			}
716			received, err := paymentReceived(s, b.CustomerID, b.Month)
717			if err != nil {
718				return fmt.Errorf("账单 %q 的收款金额与记录不一致: %w", key, err)
719			}
720			if received > payable {
721				return fmt.Errorf("账单 %q 的实收 %d 分超过当前应付 %d 分", key, received, payable)
722			}
723		}
724		return nil
725	}
