727	// validatePlanRules 校验阶梯方案的标识、名称、月费与阶梯规则本身自洽：
728	// 月费为非负整数分，至少一档，有限上限为严格递增的正整数，最后一档无
729	// 上限，单价非负。
730	func validatePlanRules(p *plan) error {
731		if p.ID == "" || p.Name == "" {
732			return fmt.Errorf("方案 %q 的标识或名称为空", p.ID)
733		}
734		if p.MonthlyFee < 0 {
735			return fmt.Errorf("方案 %q 的月费为负", p.ID)
736		}
737		if len(p.Tiers) == 0 {
738			return fmt.Errorf("方案 %q 至少需要一档阶梯", p.ID)
739		}
740		prev := int64(0)
741		for i, t := range p.Tiers {
742			if t.Price < 0 {
743				return fmt.Errorf("方案 %q 第 %d 档单价为负", p.ID, i+1)
744			}
745			if i == len(p.Tiers)-1 {
746				if t.Limit != 0 {
747					return fmt.Errorf("方案 %q 最后一档必须无上限", p.ID)
748				}
749			} else {
750				if t.Limit <= 0 {
751					return fmt.Errorf("方案 %q 第 %d 档上限必须是正整数", p.ID, i+1)
752				}
753				if t.Limit <= prev {
754					return fmt.Errorf("方案 %q 的有限上限必须严格递增", p.ID)
755				}
756				prev = t.Limit
757			}
758		}
759		return nil
760	}
