762	// tiersEqual 判定两份阶梯规则完全相同。
763	func tiersEqual(a, b []tier) bool {
764		if len(a) != len(b) {
765			return false
766		}
767		for i := range a {
768			if a[i] != b[i] {
769				return false
770			}
771		}
772		return true
773	}
774	
775	// segmentsEqual 判定两份分段列表完全相同。
776	func segmentsEqual(a, b []lineSegment) bool {
777		if len(a) != len(b) {
778			return false
779		}
780		for i := range a {
781			if a[i] != b[i] {
782				return false
783			}
784		}
785		return true
786	}
787	
788	// sortedByInstant 判定用量记录是否按（解析后的时间点升序、同一时间按
789	// 标识字典序）排列，即阶梯计价的计价顺序。
790	func sortedByInstant(recs []*usageRecord) bool {
791		for i := 1; i < len(recs); i++ {
792			ti, _ := time.Parse(time.RFC3339, recs[i-1].Time)
793			tj, _ := time.Parse(time.RFC3339, recs[i].Time)
794			ui, uj := ti.UTC(), tj.UTC()
795			if uj.Before(ui) || (uj.Equal(ui) && recs[i].ID <= recs[i-1].ID) {
796				return false
797			}
798		}
799		return true
800	}
801	
802	// validateTieredBill 校验阶梯账单：方案引用有效、快照与方案一致、账单方案
803	// 符合账期月的方案安排，并按保存的方案规则从零累计重放计价，逐条比对分段、
804	// 小计、各档合计与总金额；任何不符都视为数据损坏。
805	func (s *state) validateTieredBill(key string, b *bill, c *customer) error {
806		if b.PlanID == "" {
807			return fmt.Errorf("账单 %q 缺少方案标识", key)
808		}
809		p, ok := s.Plans[b.PlanID]
810		if !ok {
811			return fmt.Errorf("账单 %q 引用了不存在的方案 %q", key, b.PlanID)
812		}
813		if b.PlanName != p.Name {
814			return fmt.Errorf("账单 %q 的方案名称快照与方案 %q 不符", key, b.PlanID)
815		}
816		if !tiersEqual(b.PlanTiers, p.Tiers) {
817			return fmt.Errorf("账单 %q 的方案规则快照与方案 %q 不符", key, b.PlanID)
818		}
819		if b.MonthlyFee != p.MonthlyFee {
820			return fmt.Errorf("账单 %q 的月费快照与方案 %q 不符", key, b.PlanID)
821		}
822		// 账单方案必须符合账期安排：创建时绑定的初始方案被生效月不晚于
823		// 账期月的最后一次变更替换（无变更时即初始绑定，兼容旧存档）。
824		if want := s.effectivePlanID(c, b.Month); want != b.PlanID {
825			return fmt.Errorf("账单 %q 的方案 %q 与账期 %s 安排的方案 %q 不一致", key, b.PlanID, b.Month, want)
826		}
827		if b.UnitPrice != 0 {
828			return fmt.Errorf("账单 %q 是阶梯账单但保存了统一单价", key)
829		}
830		if len(b.TierTotals) != len(p.Tiers) {
831			return fmt.Errorf("账单 %q 的分档合计档数与方案规则不符", key)
832		}
833		// 明细必须按计价顺序排列（前面已逐条核验与用量记录一致）。
834		recs := make([]*usageRecord, len(b.Lines))
835		for i, ln := range b.Lines {
836			recs[i] = s.Usage[ln.UsageID]
837		}
838		if !sortedByInstant(recs) {
839			return fmt.Errorf("账单 %q 的明细未按计价顺序（时间点升序、同一时间按标识字典序）排列", key)
840		}
841		priced, err := tieredPrice(p.Tiers, recs)
842		if err != nil {
843			return fmt.Errorf("账单 %q 按方案规则计价失败: %w", key, err)
844		}
845		for i, ln := range b.Lines {
846			if !segmentsEqual(ln.Segments, priced.lines[i].segments) {
847				return fmt.Errorf("账单 %q 的明细 %q 分段与计价规则不符", key, ln.UsageID)
848			}
849			if ln.LineFee != priced.lines[i].fee {
850				return fmt.Errorf("账单 %q 的明细 %q 小计与计价规则不符", key, ln.UsageID)
851			}
852		}
853		for i, tt := range b.TierTotals {
854			if tt.Quantity != priced.tierQty[i] || tt.Fee != priced.tierFee[i] {
855				return fmt.Errorf("账单 %q 的第 %d 档合计与计价规则不符", key, i+1)
856			}
857		}
858		// 原总金额 = 月费 + 全月用量费；月费不进入分档合计与逐条小计。
859		wantTotal, err := add64(priced.totalFee, b.MonthlyFee)
860		if err != nil || wantTotal != b.TotalFee {
861			return fmt.Errorf("账单 %q 总金额不等于月费加全月用量费", key)
862		}
863		return nil
864	}
865	
866	// save 整体原子落盘：先写临时文件并同步，再 rename 覆盖。
867	// 只有完整保存成功后调用方才会向用户报告成功。
868	func (s *state) save() error {
869		if err := s.validate(); err != nil {
870			return fmt.Errorf("拒绝写入不一致的数据: %w", err)
871		}
872		data, err := json.MarshalIndent(s, "", "  ")
873		if err != nil {
874			return fmt.Errorf("序列化数据失败: %w", err)
875		}
876		data = append(data, '\n')
877	
878		tmp := s.path + ".tmp"
879		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
880		if err != nil {
881			return fmt.Errorf("写入临时数据文件失败: %w", err)
882		}
883		if _, err := f.Write(data); err != nil {
884			f.Close()
885			os.Remove(tmp)
886			return fmt.Errorf("写入临时数据文件失败: %w", err)
887		}
888		if err := f.Sync(); err != nil {
889			f.Close()
890			os.Remove(tmp)
891			return fmt.Errorf("同步数据文件失败: %w", err)
892		}
893		if err := f.Close(); err != nil {
894			os.Remove(tmp)
895			return fmt.Errorf("关闭数据文件失败: %w", err)
896		}
897		if err := os.Rename(tmp, s.path); err != nil {
898			os.Remove(tmp)
899			return fmt.Errorf("替换数据文件失败: %w", err)
900		}
901		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
902			dir.Sync()
903			dir.Close()
904		}
905		return nil
906	}
907	
908	func billKey(customerID, month string) string {
909		return customerID + "|" + month
910	}
911	
912	func planChangeKey(customerID, month string) string {
913		return customerID + "|" + month
914	}
915	
916	func suspensionKey(customerID, startMonth string) string {
917		return customerID + "|" + startMonth
918	}
919	
920	// monthInRange 判定月份 m 是否落在左闭右开区间 [start, end) 内。
921	// 月份均为已校验的 YYYY-MM，字典序即时间序。
922	func monthInRange(m, start, end string) bool {
923		return m >= start && m < end
924	}
925	
926	// suspensionsFor 返回某客户的全部暂停区间，按起月升序。
927	func (s *state) suspensionsFor(customerID string) []*suspension {
928		var list []*suspension
929		for _, su := range s.Suspensions {
930			if su.CustomerID == customerID {
931				list = append(list, su)
932			}
933		}
934		sort.Slice(list, func(i, j int) bool { return list[i].StartMonth < list[j].StartMonth })
935		return list
936	}
937	
938	// isSuspendedMonth 报告某客户的指定 UTC 自然月是否处于任一暂停区间内
939	// （区间包含起月、不包含结束月；相接区间视为连续暂停）。
940	func (s *state) isSuspendedMonth(customerID, month string) bool {
941		for _, su := range s.Suspensions {
942			if su.CustomerID == customerID && monthInRange(month, su.StartMonth, su.EndMonth) {
943				return true
944			}
945		}
946		return false
947	}
948	
949	// planChangesFor 返回某客户的全部方案变更，按生效月升序。
950	func (s *state) planChangesFor(customerID string) []*planChange {
951		var list []*planChange
952		for _, ch := range s.PlanChanges {
953			if ch.CustomerID == customerID {
954				list = append(list, ch)
955			}
956		}
957		sort.Slice(list, func(i, j int) bool { return list[i].Month < list[j].Month })
958		return list
959	}
960	
961	// effectivePlanID 返回客户在某 UTC 自然月实际适用的阶梯方案标识：
962	// 创建时绑定的初始方案，被生效月不晚于该月的最后一次变更替换。
963	func (s *state) effectivePlanID(cust *customer, month string) string {
964		planID := cust.PlanID
965		latest := ""
966		for _, ch := range s.PlanChanges {
967			if ch.CustomerID == cust.ID && ch.Month <= month && ch.Month >= latest {
968				latest = ch.Month
969				planID = ch.PlanID
970			}
971		}
972		return planID
973	}
974	
975	// sealed 报告某客户的指定月份是否已封账。
976	func (s *state) sealed(customerID, month string) bool {
977		_, ok := s.Bills[billKey(customerID, month)]
978		return ok
979	}
980	
981	// adjustmentsFor 返回某客户某月账单的全部调整，按操作序号升序。
982	func adjustmentsFor(s *state, customerID, month string) []*adjustment {
983		var list []*adjustment
984		for _, a := range s.Adjustments {
985			if a.CustomerID == customerID && a.Month == month {
986				list = append(list, a)
987			}
988		}
989		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
990		return list
991	}
992	
993	// correctionsFor 返回某收款的全部分配更正，按操作序号升序。
994	func correctionsFor(s *state, paymentID string) []*correction {
995		var list []*correction
996		for _, c := range s.Corrections {
997			if c.PaymentID == paymentID {
998				list = append(list, c)
999			}
1000		}
1001		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
1002		return list
1003	}
1004	
1005	// currentAllocations 返回一笔收款当前生效的分配：无更正时为首次登记的
1006	// 原始分配，否则为序号最大（最新）的更正的分配。
1007	func currentAllocations(s *state, p *payment) []paymentAllocation {
1008		var latest *correction
1009		for _, c := range s.Corrections {
1010			if c.PaymentID == p.ID && (latest == nil || c.Seq > latest.Seq) {
1011				latest = c
1012			}
1013		}
1014		if latest != nil {
1015			return latest.Allocations
1016		}
1017		return p.Allocations
1018	}
1019	
1020	// allocAmountFor 返回分配列表中指定月份的金额；无该月分配时为 0。
1021	func allocAmountFor(allocs []paymentAllocation, month string) int64 {
1022		for _, al := range allocs {
1023			if al.Month == month {
1024				return al.Amount
1025			}
1026		}
1027		return 0
1028	}
1029	
1030	// paymentsEverFor 返回历史上曾涉及某客户某月账单的全部收款（首次登记
1031	// 分配或任一次更正的新分配涉及该月，即使后来被更正移出），按操作序号升序。
1032	func paymentsEverFor(s *state, customerID, month string) []*payment {
1033		var list []*payment
1034		for _, p := range s.Payments {
1035			if p.CustomerID != customerID {
1036				continue
1037			}
1038			involved := p.amountFor(month) > 0
1039			if !involved {
1040				for _, c := range s.Corrections {
1041					if c.PaymentID == p.ID && allocAmountFor(c.Allocations, month) > 0 {
1042						involved = true
1043						break
1044					}
1045				}
1046			}
1047			if involved {
1048				list = append(list, p)
1049			}
1050		}
1051		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
1052		return list
1053	}
1054	
1055	// paymentReceived 返回全部未撤销收款按最新分配在指定月份计入的实收之和。
1056	// 各笔分配均为正整数，用非负 64 位加法累加，溢出时返回错误。
1057	func paymentReceived(s *state, customerID, month string) (int64, error) {
1058		var received int64
1059		for _, p := range s.Payments {
1060			if p.CustomerID != customerID || p.Revoked {
1061				continue
1062			}
1063			amt := allocAmountFor(currentAllocations(s, p), month)
1064			if amt <= 0 {
1065				continue
1066			}
1067			var err error
1068			received, err = add64(received, amt)
1069			if err != nil {
1070				return 0, err
1071			}
1072		}
1073		return received, nil
1074	}
1075	
1076	// errPayableOutOfRange 表示当前应付越出 [0, 有符号 64 位最大值]。
1077	var errPayableOutOfRange = errors.New("当前应付越界（须介于 0 与有符号 64 位最大值之间）")
1078	
1079	// billTotals 计算全部未撤销调整的净额与当前应付（原总金额 + 净额）。
1080	// 净额按 128 位精确求和（与顺序无关），再校验应付落在
1081	// [0, 有符号 64 位最大值] 内，全程整数运算。
1082	func billTotals(b *bill, adjs []*adjustment) (net, payable int64, err error) {
1083		var amounts []int64
1084		for _, a := range adjs {
1085			if !a.Revoked {
1086				amounts = append(amounts, a.Amount)
1087			}
1088		}
1089		net, err = sumSigned64(amounts...)
1090		if err != nil {
1091			return 0, 0, err
1092		}
1093		payable, err = addSigned64(b.TotalFee, net)
1094		if err != nil {
1095			return 0, 0, err
1096		}
1097		if payable < 0 {
1098			return 0, 0, errPayableOutOfRange
1099		}
1100		return net, payable, nil
1101	}
