194	func cmdCustomerAdd(dir, id, name, priceText string) error {
195		if strings.TrimSpace(id) == "" {
196			return fmt.Errorf("客户标识不能为空")
197		}
198		if strings.TrimSpace(name) == "" {
199			return fmt.Errorf("客户名称不能为空")
200		}
201		price, err := parsePrice(priceText)
202		if err != nil {
203			return err
204		}
205	
206		s, err := loadStore(dir)
207		if err != nil {
208			return err
209		}
210		if _, exists := s.Customers[id]; exists {
211			return fmt.Errorf("客户标识 %q 已存在，客户单价创建后不可修改", id)
212		}
213		s.Customers[id] = &customer{ID: id, Name: name, Price: price}
214		if err := s.save(); err != nil {
215			return err
216		}
217		fmt.Fprintf(stdout, "已登记客户 %q（%s），固定单价 %d 分（%s）\n", id, name, price, moneyFen(price))
218		return nil
219	}
