221	func parsePrice(text string) (int64, error) {
222		text = strings.TrimSpace(text)
223		price, err := strconv.ParseInt(text, 10, 64)
224		if err != nil {
225			return 0, fmt.Errorf("单价 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
226		}
227		if price < 0 {
228			return 0, fmt.Errorf("单价必须是非负整数分，收到 %d", price)
229		}
230		return price, nil
231	}
