233	// parsedRow 是导入文件中一行解析后的候选用量。
234	type parsedRow struct {
235		line int // 文件中的行号（含表头），用于报错定位
236		rec  usageRecord
237		t    time.Time
238	}
239	
240	func cmdUsageImport(dir, file string) error {
241		var reader io.ReadCloser
242		var source string
243		if file == "-" {
244			reader = io.NopCloser(os.Stdin)
245			source = "标准输入"
246		} else {
247			f, err := os.Open(file)
248			if err != nil {
249				return fmt.Errorf("无法打开用量文件 %s: %w", file, err)
250			}
251			reader = f
252			source = file
253		}
254		defer reader.Close()
255	
256		rows, parseErrs := parseUsageFile(reader)
257	
258		s, err := loadStore(dir)
259		if err != nil {
260			return err
261		}
262	
263		// 先校验：任何问题都在此阶段收集，全部通过后才一次性修改并保存，
264		// 保证“整批导入先校验再生效”，失败不留下任何新用量。
265		var problems []string
266		problems = append(problems, parseErrs...)
267	
268		accepted := make(map[string]*parsedRow) // 本批内首次出现、内容确定的记录
269		var ordered []*parsedRow
270		newCount, dupCount := 0, 0
271	
272		for _, r := range rows {
273			cust, ok := s.Customers[r.rec.CustomerID]
274			if !ok {
275				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识 %q 不存在", r.line, r.rec.CustomerID))
276				continue
277			}
278			// 暂停月的新用量一律拒绝：按记录时间换算的 UTC 月份判断，处于任一
279			// 暂停区间（含起月、不含结束月）即整批失败并指出行号；库中已有的
280			// 相同记录仍按下面的去重规则处理（合法存档的暂停月不会已有用量）。
281			rowMonth := r.t.UTC().Format("2006-01")
282			if s.isSuspendedMonth(r.rec.CustomerID, rowMonth) {
283				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 处于暂停区间，暂停服务期间不接收用量（新用量 %q 被拒绝）",
284					r.line, r.rec.CustomerID, rowMonth, r.rec.ID))
285				continue
286			}
287			// 金额可行性预检：固定单价客户检查 数量×单价；阶梯客户按记录时间
288			// 换算的 UTC 月份的有效方案，以单条数量从零计价，检查分段金额不
289			// 溢出（金额单位：分）。
290			if cust.PlanID == "" {
291				if _, err := mul64(r.rec.Quantity, cust.Price); err != nil {
292					problems = append(problems, fmt.Sprintf("第 %d 行：数量 %d × 单价 %d 金额溢出有符号 64 位整数范围", r.line, r.rec.Quantity, cust.Price))
293					continue
294				}
295			} else {
296				rec := r.rec
297				planID := s.effectivePlanID(cust, rowMonth)
298				if _, err := tieredPrice(s.Plans[planID].Tiers, []*usageRecord{&rec}); err != nil {
299					problems = append(problems, fmt.Sprintf("第 %d 行：按 %s 月有效方案 %q 对单条数量从零计价失败：%v", r.line, rowMonth, planID, err))
300					continue
301				}
302			}
303	
304			// 去重判定同时对“库中已有”和“本文件内已出现”生效。
305			var existing *usageRecord
306			if inStore, ok := s.Usage[r.rec.ID]; ok {
307				existing = inStore
308			} else if inBatch, ok := accepted[r.rec.ID]; ok {
309				existing = &inBatch.rec
310			}
311	
312			if existing != nil {
313				if !sameUsage(existing, &r.rec, r.t) {
314					problems = append(problems, fmt.Sprintf("第 %d 行：用量标识 %q 已存在但内容不同（已有客户=%s 时间=%s 数量=%d）",
315						r.line, r.rec.ID, existing.CustomerID, existing.Time, existing.Quantity))
316					continue
317				}
318				dupCount++
319				continue
320			}
321	
322			// 全新标识：不得进入该客户已封账的 UTC 自然月。
323			month := r.t.UTC().Format("2006-01")
324			if s.sealed(r.rec.CustomerID, month) {
325				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 已封账，新用量 %q 不得进入",
326					r.line, r.rec.CustomerID, month, r.rec.ID))
327				continue
328			}
329	
330			rr := r
331			accepted[r.rec.ID] = rr
332			ordered = append(ordered, rr)
333			newCount++
334		}
335	
336		if len(problems) > 0 {
337			return fmt.Errorf("导入失败，整批未生效（共 %d 个问题）：\n  %s", len(problems), strings.Join(problems, "\n  "))
338		}
339	
340		for _, r := range ordered {
341			rec := r.rec
342			s.Usage[rec.ID] = &rec
343		}
344		if err := s.save(); err != nil {
345			return err
346		}
347		fmt.Fprintf(stdout, "导入完成（%s）：新增 %d 条，重复跳过 %d 条\n", source, newCount, dupCount)
348		return nil
349	}
