351	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
352	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
353		cr := csv.NewReader(r)
354		cr.FieldsPerRecord = 4
355		cr.TrimLeadingSpace = true
356	
357		header, err := cr.Read()
358		if err == io.EOF {
359			return nil, []string{"文件为空：首行必须是表头 " + usageHeader}
360		}
361		if err != nil {
362			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, usageHeader)}
363		}
364		for i := range header {
365			header[i] = strings.TrimSpace(header[i])
366		}
367		if len(header) != 4 || header[0] != "usage_id" || header[1] != "customer_id" ||
368			header[2] != "time" || header[3] != "quantity" {
369			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", usageHeader, strings.Join(header, ","))}
370		}
371	
372		var rows []*parsedRow
373		var problems []string
374		line := 1
375		for {
376			rec, err := cr.Read()
377			if err == io.EOF {
378				break
379			}
380			line++
381			if err != nil {
382				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
383				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
384					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
385					break
386				}
387				continue
388			}
389			for i := range rec {
390				rec[i] = strings.TrimSpace(rec[i])
391			}
392	
393			id, custID, ts, qtyText := rec[0], rec[1], rec[2], rec[3]
394			if id == "" {
395				problems = append(problems, fmt.Sprintf("第 %d 行：用量标识不能为空", line))
396				continue
397			}
398			if custID == "" {
399				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
400				continue
401			}
402			t, err := time.Parse(time.RFC3339, ts)
403			if err != nil {
404				problems = append(problems, fmt.Sprintf("第 %d 行：时间 %q 不是 RFC3339 格式：%v", line, ts, err))
405				continue
406			}
407			qty, err := strconv.ParseInt(qtyText, 10, 64)
408			if err != nil {
409				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %q 不是有符号 64 位整数", line, qtyText))
410				continue
411			}
412			if qty <= 0 {
413				problems = append(problems, fmt.Sprintf("第 %d 行：数量必须是正整数，收到 %d", line, qty))
414				continue
415			}
416	
417			rows = append(rows, &parsedRow{
418				line: line,
419				rec:  usageRecord{ID: id, CustomerID: custID, Time: ts, Quantity: qty},
420				t:    t,
421			})
422		}
423		return rows, problems
424	}
425	
426	// sameUsage 按（客户、解析后的时间点、数量）判定两条记录内容是否相同，
427	// 时间比较的是瞬间，因此 Z 与 +08:00 表示同一时刻视为相同。
428	func sameUsage(existing *usageRecord, candidate *usageRecord, candidateT time.Time) bool {
429		if existing.CustomerID != candidate.CustomerID || existing.Quantity != candidate.Quantity {
430			return false
431		}
432		et, err := time.Parse(time.RFC3339, existing.Time)
433		if err != nil {
434			return existing.Time == candidate.Time
435		}
436		return et.Equal(candidateT)
437	}
438	
439	// validMonth 严格校验 YYYY-MM（月份两位、01..12）。
440	func validMonth(m string) bool {
441		t, err := time.Parse("2006-01", m)
442		if err != nil || t.Format("2006-01") != m || t.Year() < 1 {
443			return false
444		}
445		return true
446	}
447	
448	// inMonth 判定一条 RFC3339 时间（换算 UTC 后）是否落在给定自然月。
449	func inMonth(rfc3339, month string) bool {
450		t, err := time.Parse(time.RFC3339, rfc3339)
451		if err != nil {
452			return false
453		}
454		return t.UTC().Format("2006-01") == month
455	}
456	
457	// utcMonth 返回 RFC3339 时间换算 UTC 后的自然月（YYYY-MM）。
458	// 入参时间均已在载入/导入时校验为 RFC3339。
459	func utcMonth(rfc3339 string) string {
460		t, _ := time.Parse(time.RFC3339, rfc3339)
461		return t.UTC().Format("2006-01")
462	}
