464	func cmdBillSettle(dir, customerID, month string) error {
465		if !validMonth(month) {
466			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
467		}
468		s, err := loadStore(dir)
469		if err != nil {
470			return err
471		}
472		cust, ok := s.Customers[customerID]
473		if !ok {
474			return fmt.Errorf("客户标识 %q 不存在", customerID)
475		}
476	
477		// 暂停月无论方案月费多少都拒绝结算：不封账、不生成零金额账单。
478		if s.isSuspendedMonth(customerID, month) {
479			return fmt.Errorf("客户 %s 的 %s 处于暂停区间，暂停服务期间不产生月费账单，拒绝结算且不封账", customerID, month)
480		}
481	
482		key := billKey(customerID, month)
483		if existing, ok := s.Bills[key]; ok {
484			// 幂等：同一客户同一月份重复结算，直接返回原账单，
485			// 不重新计费、不产生新账单或调整、不落盘。
486			fmt.Fprintf(stdout, "客户 %s 的 %s 已结算，返回原账单（幂等，不重新计费）：\n\n", customerID, month)
487			printBill(existing, cust, s)
488			return nil
489		}
490	
491		// 归集该客户 UTC 自然月内的全部用量，区间为左闭右开 [月初, 下月初)。
492		// 有效方案月费大于 0 的阶梯客户即使无用量也须出账（收取一次整月月费）；
493		// 月费为 0 的方案与固定单价客户无用量时仍拒绝结算且不封账。
494		inMonthRecs := monthUsage(s, customerID, month)
495		if len(inMonthRecs) == 0 && !monthlyFeeBillable(s, cust, month) {
496			return fmt.Errorf("客户 %s 在 %s 没有用量，拒绝结算且不封账", customerID, month)
497		}
498	
499		// 绑定阶梯方案的客户走按月累计分档计价；固定单价客户保持原路径。
500		if cust.PlanID != "" {
501			return settleTiered(s, cust, month, inMonthRecs)
502		}
503	
504		b, err := buildFixedBill(cust, month, inMonthRecs)
505		if err != nil {
506			return fmt.Errorf("%v，拒绝结算且不封账", err)
507		}
508		s.Bills[key] = b
509	
510		// 账单与封账状态在同一次原子保存中一起持久化；保存失败则一切不生效。
511		if err := s.save(); err != nil {
512			delete(s.Bills, key)
513			return err
514		}
515		fmt.Fprintf(stdout, "结算完成，客户 %s 的 %s 已封账：\n\n", customerID, month)
516		printBill(b, cust, s)
517		return nil
518	}
