540	// monthUsage 归集客户在某 UTC 自然月（左闭右开 [月初, 下月初)）内的全部
541	// 用量，并按计价顺序（解析后的时间点升序、同一时间按标识字典序）排列。
542	func monthUsage(s *state, customerID, month string) []*usageRecord {
543		var recs []*usageRecord
544		for _, u := range s.Usage {
545			if u.CustomerID == customerID && inMonth(u.Time, month) {
546				recs = append(recs, u)
547			}
548		}
549		sortByInstant(recs)
550		return recs
551	}
