553	// buildFixedBill 为固定单价客户构造账单（不落盘）：逐条 数量×单价 并汇总，
554	// 全程整数运算，任何一步溢出都返回错误。recs 须已按计价顺序排列。
555	func buildFixedBill(cust *customer, month string, recs []*usageRecord) (*bill, error) {
556		lines := make([]billLine, 0, len(recs))
557		var totalQty, totalFee int64
558		for _, u := range recs {
559			lineFee, err := mul64(u.Quantity, cust.Price)
560			if err != nil {
561				return nil, fmt.Errorf("用量 %s：数量 %d × 单价 %d 金额溢出", u.ID, u.Quantity, cust.Price)
562			}
563			if totalQty, err = add64(totalQty, u.Quantity); err != nil {
564				return nil, fmt.Errorf("汇总数量溢出有符号 64 位整数范围")
565			}
566			if totalFee, err = add64(totalFee, lineFee); err != nil {
567				return nil, fmt.Errorf("汇总金额溢出有符号 64 位整数范围")
568			}
569			lines = append(lines, billLine{
570				UsageID:  u.ID,
571				Time:     u.Time,
572				Quantity: u.Quantity,
573				LineFee:  lineFee,
574			})
575		}
576		return &bill{
577			ID:         stableBillID(cust.ID, month),
578			CustomerID: cust.ID,
579			Month:      month,
580			TotalQty:   totalQty,
581			UnitPrice:  cust.Price,
582			TotalFee:   totalFee,
583			Lines:      lines,
584			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
585		}, nil
586	}
587	
588	func sortByInstant(us []*usageRecord) {
589		// 入参时间均已在载入/导入时校验为 RFC3339。
590		sort.Slice(us, func(i, j int) bool {
591			ti, _ := time.Parse(time.RFC3339, us[i].Time)
592			tj, _ := time.Parse(time.RFC3339, us[j].Time)
593			ui, uj := ti.UTC(), tj.UTC()
594			if !ui.Equal(uj) {
595				return ui.Before(uj)
596			}
597			return us[i].ID < us[j].ID
598		})
599	}
