609		// 收款历史保留所有曾涉及本账单的收款：首次登记或任一次更正分配
610		// 涉及该月即纳入，即使后来被更正移出。
611		pays := paymentsEverFor(s, b.CustomerID, b.Month)
612		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
613		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
614		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
615		tiered := b.Pricing == "tiered"
616		if tiered {
617			// 阶梯账单明确计价类型并展示方案与完整规则，不伪造统一单价。
618			fmt.Fprintf(stdout, "计价类型：阶梯计费（按 UTC 自然月累计用量分档计价，每月从零累计）\n")
619			fmt.Fprintf(stdout, "方案：%s（%s）\n", b.PlanID, b.PlanName)
