624				} else {
625					fmt.Fprintf(stdout, "  第 %d 档：累计上限 %d，单价 %d 分（%s）\n", i+1, t.Limit, t.Price, moneyFen(t.Price))
626				}
627			}
628		} else {
629			fmt.Fprintf(stdout, "单价：%d 分（%s）\n", b.UnitPrice, moneyFen(b.UnitPrice))
630		}
631		fmt.Fprintf(stdout, "总数量：%d\n", b.TotalQty)
632		if tiered {
633			// 阶梯账单分列月费与用量费：原总金额 = 月费 + 全月用量费；
634			// 月费不计入总数量、各档金额或逐条小计。
635			usageFee := b.TotalFee - b.MonthlyFee
636			fmt.Fprintf(stdout, "月费：%d 分（%s，整月收取，不按天折算）\n", b.MonthlyFee, moneyFen(b.MonthlyFee))
637			fmt.Fprintf(stdout, "用量费：%d 分（%s）\n", usageFee, moneyFen(usageFee))
638			fmt.Fprintf(stdout, "原总金额：%d 分（%s，月费加全月用量费）\n", b.TotalFee, moneyFen(b.TotalFee))
639		} else {
640			fmt.Fprintf(stdout, "总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
641		}
642		if tiered {
643			fmt.Fprintln(stdout, "各档合计：")
644			for i, tt := range b.TierTotals {
645				fmt.Fprintf(stdout, "  第 %d 档：数量 %d，单价 %d 分，金额 %d 分（%s）\n",
646					i+1, tt.Quantity, b.PlanTiers[i].Price, tt.Fee, moneyFen(tt.Fee))
647			}
648		}
649		// 数据在载入时已校验一致，此处计算不会出错。
650		net, payable, _ := billTotals(b, adjs)
651		received, _ := paymentReceived(s, b.CustomerID, b.Month)
652		outstanding := payable - received // 不变量保证 0 ≤ 实收 ≤ 当前应付
653		fmt.Fprintf(stdout, "调整净额：%+d 分（%s）\n", net, moneyFen(net))
654		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
655		fmt.Fprintf(stdout, "实收：%d 分（%s）\n", received, moneyFen(received))
656		fmt.Fprintf(stdout, "未收余额：%d 分（%s）\n", outstanding, moneyFen(outstanding))
657		if len(b.Lines) == 0 {
658			fmt.Fprintln(stdout, "明细：无（本账期无用量，仅收取月费）")
659		} else {
660			fmt.Fprintln(stdout, "明细：")
661		}
662		for i, ln := range b.Lines {
663			fmt.Fprintf(stdout, "  %d. 用量标识=%s 时间=%s 数量=%d 小计=%d 分（%s）\n",
