668					j+1, seg.Tier+1, seg.Quantity, b.PlanTiers[seg.Tier].Price, seg.Fee, moneyFen(seg.Fee))
669			}
670		}
671		if len(adjs) == 0 {
672			fmt.Fprintln(stdout, "调整与撤销历史：无")
673		} else {
674			fmt.Fprintln(stdout, "调整与撤销历史（按成功操作顺序）：")
675			for i, ev := range historyEvents(adjs) {
676				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
677			}
678		}
679		if len(pays) == 0 {
680			fmt.Fprintln(stdout, "收款与撤销历史：无")
681		} else {
682			fmt.Fprintln(stdout, "收款与撤销历史（按成功操作顺序）：")
683			for i, ev := range paymentHistoryEvents(s, pays, b.Month) {
684				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
685			}
686		}
687	}
