689	// historyEvents 把调整与撤销展开为按操作序号排序的可读历史条目。
690	func historyEvents(adjs []*adjustment) []string {
691		type event struct {
692			seq  int64
693			text string
694		}
695		var events []event
696		for _, a := range adjs {
697			events = append(events, event{a.Seq, fmt.Sprintf("调整 %s：%s %+d 分（%s），原因：%s，当前状态：%s",
698				a.ID, adjustKind(a.Amount), a.Amount, moneyFen(a.Amount), a.Reason, adjustStatus(a))})
699			if a.Revoked {
700				events = append(events, event{a.RevokeSeq, fmt.Sprintf("撤销 %s：原因：%s（关联调整 %s 的%s %+d 分）",
701					a.ID, a.RevokeReason, a.ID, adjustKind(a.Amount), a.Amount)})
702			}
703		}
704		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
705		out := make([]string, len(events))
706		for i, ev := range events {
707			out[i] = ev.text
708		}
709		return out
710	}
711	
712	func adjustKind(amount int64) string {
713		if amount > 0 {
714			return "补收"
715		}
716		return "减免"
717	}
718	
719	func adjustStatus(a *adjustment) string {
720		if a.Revoked {
721			return "已撤销"
722		}
723		return "生效中"
724	}
