726	// paymentHistoryEvents 把收款登记、分配更正与撤销展开为按操作序号排序的
727	// 可读历史条目；month 为当前展示账单所在月份。收款事件展示首次登记时在
728	// 本账单的分配，更正事件展示本账单分配的前后变化，撤销事件展示被整笔取消
729	// 的最新分配。
730	func paymentHistoryEvents(s *state, pays []*payment, month string) []string {
731		type event struct {
732			seq  int64
733			text string
734		}
735		var events []event
736		for _, p := range pays {
737			alloc := p.amountFor(month)
738			events = append(events, event{p.Seq, fmt.Sprintf("收款 %s：总额 %d 分（%s），本账单分配 %d 分（%s），备注：%s，当前状态：%s（客户 %s）",
739				p.ID, p.Total, moneyFen(p.Total), alloc, moneyFen(alloc), p.Note, paymentStatus(p), p.CustomerID)})
740			// 以首次登记分配为起点，按序号回放该收款在本账单的分配变化。
741			running := alloc
742			for _, c := range correctionsFor(s, p.ID) {
743				after := allocAmountFor(c.Allocations, month)
744				if running == 0 && after == 0 {
745					continue // 本次更正不涉及本账单
746				}
747				events = append(events, event{c.Seq, fmt.Sprintf("更正 %s：原因：%s（关联收款 %s，本账单分配 %d 分 → %d 分）",
748					c.ID, c.Reason, p.ID, running, after)})
749				running = after
750			}
751			if p.Revoked {
752				// 整笔撤销取消的是撤销时的最新分配。
753				events = append(events, event{p.RevokeSeq, fmt.Sprintf("撤销收款 %s：原因：%s（关联收款 %s，总额 %d 分，本账单分配 %d 分）",
754					p.ID, p.RevokeReason, p.ID, p.Total, running)})
755			}
756		}
757		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
758		out := make([]string, len(events))
759		for i, ev := range events {
760			out[i] = ev.text
761		}
762		return out
763	}
764	
765	func paymentStatus(p *payment) string {
766		if p.Revoked {
767			return "已撤销"
768		}
769		return "实收中"
770	}
