772	// parseAmount 解析调整金额：有符号 64 位整数、非零（正数补收、负数减免）。
773	func parseAmount(text string) (int64, error) {
774		text = strings.TrimSpace(text)
775		amount, err := strconv.ParseInt(text, 10, 64)
776		if err != nil {
777			return 0, fmt.Errorf("调整金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
778		}
779		if amount == 0 {
780			return 0, fmt.Errorf("调整金额不能为零分（正数补收、负数减免）")
781		}
782		return amount, nil
783	}
