785	func cmdBillAdjust(dir, customerID, month, adjID, amountText, reason string) error {
786		if !validMonth(month) {
787			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
788		}
789		if strings.TrimSpace(adjID) == "" {
790			return fmt.Errorf("调整标识不能为空")
791		}
792		amount, err := parseAmount(amountText)
793		if err != nil {
794			return err
795		}
796		if strings.TrimSpace(reason) == "" {
797			return fmt.Errorf("调整原因不能为空")
798		}
799	
800		s, err := loadStore(dir)
801		if err != nil {
802			return err
803		}
804		if _, ok := s.Customers[customerID]; !ok {
805			return fmt.Errorf("客户标识 %q 不存在", customerID)
806		}
807		b, ok := s.Bills[billKey(customerID, month)]
808		if !ok {
809			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），费用调整只能作用于已存在账单", customerID, month)
810		}
811	
812		if existing, ok := s.Adjustments[adjID]; ok {
813			// 相同标识按客户、月份、金额、原因判断重复：内容相同返回已保存
814			// 记录，不再次增减应付；已撤销的重放仍返回已撤销状态，不重新生效。
815			if existing.CustomerID == customerID && existing.Month == month &&
816				existing.Amount == amount && existing.Reason == reason {
817				fmt.Fprintf(stdout, "调整 %q 已存在且内容相同，返回已保存记录（不重复增减应付）：\n\n", adjID)
818				printAdjustment(existing, s)
819				return nil
820			}
821			return fmt.Errorf("调整标识 %q 已存在但内容不同（已有：客户=%s 月份=%s 金额=%d 原因=%q），拒绝复用",
822				adjID, existing.CustomerID, existing.Month, existing.Amount, existing.Reason)
823		}
824	
825		// 应付可行性预检：原总金额 + 全部未撤销调整 + 本次金额必须落在
826		// [0, 有符号 64 位最大值] 内，且不得低于已登记实收，否则拒绝且
827		// 不占用该调整标识。
828		_, payable, err := billTotals(b, adjustmentsFor(s, customerID, month))
829		if err != nil {
830			return fmt.Errorf("账单当前应付异常，拒绝调整: %w", err)
831		}
832		received, err := paymentReceived(s, customerID, month)
833		if err != nil {
834			return fmt.Errorf("实收累计异常，拒绝调整: %w", err)
835		}
836		newPayable, err := addSigned64(payable, amount)
837		if err != nil {
838			return fmt.Errorf("调整后当前应付超出有符号 64 位最大值（当前 %d 分，本次 %+d 分），拒绝调整", payable, amount)
839		}
840		if newPayable < 0 {
841			return fmt.Errorf("调整后当前应付将为 %d 分（小于 0，当前 %d 分，本次 %+d 分），拒绝调整", newPayable, payable, amount)
842		}
843		if newPayable < received {
844			return fmt.Errorf("调整后当前应付 %d 分将低于实收 %d 分（当前 %d 分，本次 %+d 分），拒绝调整；可先撤销误登记的收款再重试",
845				newPayable, received, payable, amount)
846		}
847	
848		a := &adjustment{
849			ID:         adjID,
850			CustomerID: customerID,
851			Month:      month,
852			Amount:     amount,
853			Reason:     reason,
854			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
855		}
856		s.NextSeq++
857		a.Seq = s.NextSeq
858		s.Adjustments[adjID] = a
859	
860		// 调整记录与序号在同一次原子保存中持久化；保存失败则一切不生效，
861		// 该调整标识不被占用。
862		if err := s.save(); err != nil {
863			delete(s.Adjustments, adjID)
864			s.NextSeq--
865			return err
866		}
867		fmt.Fprintf(stdout, "已登记%s调整 %q，客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
868			adjustKind(amount), adjID, customerID, month, newPayable, moneyFen(newPayable))
869		printAdjustment(a, s)
870		return nil
871	}
