873	func cmdBillRevoke(dir, adjID, reason string) error {
874		if strings.TrimSpace(adjID) == "" {
875			return fmt.Errorf("调整标识不能为空")
876		}
877		if strings.TrimSpace(reason) == "" {
878			return fmt.Errorf("撤销原因不能为空")
879		}
880	
881		s, err := loadStore(dir)
882		if err != nil {
883			return err
884		}
885		a, ok := s.Adjustments[adjID]
886		if !ok {
887			return fmt.Errorf("调整标识 %q 不存在，无法撤销", adjID)
888		}
889	
890		if a.Revoked {
891			// 相同标识与相同原因重复撤销：幂等成功，不新增记录；
892			// 改用其他原因则拒绝。
893			if a.RevokeReason == reason {
894				fmt.Fprintf(stdout, "调整 %q 已撤销且撤销原因相同，幂等返回（不新增记录）：\n\n", adjID)
895				printAdjustment(a, s)
896				return nil
897			}
898			return fmt.Errorf("调整 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", adjID, a.RevokeReason)
899		}
900	
901		// 撤销只取消该笔调整的金额影响；若撤销后当前应付越界或低于实收则
902		// 拒绝，该调整仍保持有效，可先撤销误登记的收款或在其他合法调整
903		// 改变余额后重试。
904		b := s.Bills[billKey(a.CustomerID, a.Month)] // 载入时已校验存在
905		_, payable, err := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
906		if err != nil {
907			return fmt.Errorf("账单当前应付异常，拒绝撤销: %w", err)
908		}
909		received, err := paymentReceived(s, a.CustomerID, a.Month)
910		if err != nil {
911			return fmt.Errorf("实收累计异常，拒绝撤销: %w", err)
912		}
913		neg, err := neg64(a.Amount)
914		if err != nil {
915			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值，拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试")
916		}
917		newPayable, err := addSigned64(payable, neg)
918		if err != nil {
919			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值（当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
920				payable, a.Amount)
921		}
922		if newPayable < 0 {
923			return fmt.Errorf("撤销后当前应付将为 %d 分（小于 0，当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
924				newPayable, payable, a.Amount)
925		}
926		if newPayable < received {
927			return fmt.Errorf("撤销后当前应付 %d 分将低于实收 %d 分（当前 %d 分，取消 %+d 分），拒绝撤销；可先撤销误登记的收款再重试",
928				newPayable, received, payable, a.Amount)
929		}
930	
931		a.Revoked = true
932		a.RevokeReason = reason
933		a.RevokedAt = time.Now().UTC().Format(time.RFC3339)
934		s.NextSeq++
935		a.RevokeSeq = s.NextSeq
936	
937		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
938		if err := s.save(); err != nil {
939			a.Revoked = false
940			a.RevokeReason = ""
941			a.RevokedAt = ""
942			a.RevokeSeq = 0
943			s.NextSeq--
944			return err
945		}
946		fmt.Fprintf(stdout, "已撤销调整 %q（%s %+d 分），客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
947			adjID, adjustKind(a.Amount), a.Amount, a.CustomerID, a.Month, newPayable, moneyFen(newPayable))
948		printAdjustment(a, s)
949		return nil
950	}
