969	// parsePositiveAmount 解析收款金额：正整数分（不接受零、负数、小数）。
970	func parsePositiveAmount(text string) (int64, error) {
971		text = strings.TrimSpace(text)
972		amount, err := strconv.ParseInt(text, 10, 64)
973		if err != nil {
974			return 0, fmt.Errorf("收款金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
975		}
976		if amount <= 0 {
977			return 0, fmt.Errorf("收款金额必须是正整数分，收到 %d", amount)
978		}
979		return amount, nil
980	}
