995	func cmdBillRemit(dir, customerID, payID, totalText, note string, allocArgs []string) error {
996		total, err := parsePositiveAmount(totalText)
997		if err != nil {
998			return err
999		}
1000		allocs, err := parseAllocations(allocArgs)
1001		if err != nil {
1002			return err
1003		}
1004		// 分配合计必须等于总额，全程整数运算，溢出拒绝。
1005		var sum int64
1006		for _, al := range allocs {
1007			sum, err = add64(sum, al.Amount)
1008			if err != nil {
1009				return fmt.Errorf("分配金额合计溢出有符号 64 位整数范围，拒绝登记")
1010			}
1011		}
1012		if sum != total {
1013			return fmt.Errorf("分配合计 %d 分与收款总额 %d 分不一致，拒绝登记", sum, total)
1014		}
