1018	// parseAllocations 解析 <YYYY-MM:金额分> 形式的分配列表：至少一项，
1019	// 月份不得重复，每项金额为正整数分。
1020	func parseAllocations(args []string) ([]paymentAllocation, error) {
1021		if len(args) == 0 {
1022			return nil, fmt.Errorf("分配列表不能为空，至少需要一项 <YYYY-MM:金额分>")
1023		}
1024		seen := make(map[string]bool)
1025		allocs := make([]paymentAllocation, 0, len(args))
1026		for _, arg := range args {
1027			parts := strings.Split(arg, ":")
1028			if len(parts) != 2 {
1029				return nil, fmt.Errorf("分配项 %q 格式非法，应为 YYYY-MM:金额分（如 2026-09:500）", arg)
1030			}
1031			month := strings.TrimSpace(parts[0])
1032			if !validMonth(month) {
1033				return nil, fmt.Errorf("分配项 %q 的月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", arg, parts[0])
1034			}
1035			if seen[month] {
1036				return nil, fmt.Errorf("分配月份 %s 重复，拒绝登记", month)
1037			}
1038			seen[month] = true
1039			amount, err := parsePositiveAmount(parts[1])
1040			if err != nil {
1041				return nil, fmt.Errorf("分配项 %q 的金额无效: %w", arg, err)
1042			}
1043			allocs = append(allocs, paymentAllocation{Month: month, Amount: amount})
1044		}
1045		return allocs, nil
1046	}
