1048	// registerPayment 是 bill pay 与 bill remit 共用的收款登记核心：
1049	// 先整体校验再整笔生效，任何一项不合法都不落盘、不占用收款标识。
1050	func registerPayment(dir, customerID, payID string, total int64, note string, allocs []paymentAllocation) error {
1051		if strings.TrimSpace(payID) == "" {
1052			return fmt.Errorf("收款标识不能为空")
1053		}
1054		if strings.TrimSpace(note) == "" {
1055			return fmt.Errorf("收款备注不能为空")
1056		}
1057		// 分配顺序不影响收款身份：统一按月份升序保存与比较。
1058		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1059	
1060		s, err := loadStore(dir)
1061		if err != nil {
1062			return err
1063		}
1064		if _, ok := s.Customers[customerID]; !ok {
1065			return fmt.Errorf("客户标识 %q 不存在", customerID)
1066		}
1067		for _, al := range allocs {
1068			if _, ok := s.Bills[billKey(customerID, al.Month)]; !ok {
1069				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），收款只能登记到已存在账单", customerID, al.Month)
1070			}
1071		}
1072	
1073		if existing, ok := s.Payments[payID]; ok {
1074			// 相同标识按客户、总额、备注与月份-金额对应关系判断重复：内容相同
1075			// 返回已保存记录，不再次计入实收，也不受当前余额变化影响；
1076			// 已撤销的重放仍返回已撤销状态，不恢复实收。
1077			if samePaymentContent(existing, customerID, total, note, allocs) {
1078				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同，返回已保存记录（不重复计入实收）：\n\n", payID)
1079				printPayment(existing, s)
1080				return nil
1081			}
1082			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q 分配=%s），拒绝复用",
1083				payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1084		}
1085	
1086		// 首次登记：每项分配不得超过对应账单的未收余额，全部合法才整笔生效。
1087		for _, al := range allocs {
1088			b := s.Bills[billKey(customerID, al.Month)]
1089			_, payable, err := billTotals(b, adjustmentsFor(s, customerID, al.Month))
1090			if err != nil {
1091				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝登记收款: %w", customerID, al.Month, err)
1092			}
1093			received, err := paymentReceived(s, customerID, al.Month)
1094			if err != nil {
1095				return fmt.Errorf("客户 %s 的 %s 实收累计溢出有符号 64 位整数范围，拒绝登记收款: %w", customerID, al.Month, err)
1096			}
1097			if payable == 0 {
1098				return fmt.Errorf("客户 %s 的 %s 当前应付为 0 分，不能登记正额收款", customerID, al.Month)
1099			}
1100			if al.Amount > payable-received {
1101				return fmt.Errorf("分配 %d 分超过未收余额 %d 分（客户 %s 的 %s：当前应付 %d 分，实收 %d 分），拒绝登记",
1102					al.Amount, payable-received, customerID, al.Month, payable, received)
1103			}
1104		}
1105	
1106		p := &payment{
1107			ID:          payID,
1108			CustomerID:  customerID,
1109			Total:       total,
1110			Note:        note,
1111			Allocations: allocs,
1112			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1113		}
1114		s.NextSeq++
1115		p.Seq = s.NextSeq
1116		s.Payments[payID] = p
1117	
1118		// 收款记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1119		// 一切不生效，该收款标识不被占用。
1120		if err := s.save(); err != nil {
1121			delete(s.Payments, payID)
1122			s.NextSeq--
1123			return err
1124		}
1125		fmt.Fprintf(stdout, "已登记收款 %q（总额 %d 分，%s）：\n", payID, total, moneyFen(total))
1126		printAllocationBalances(s, p, allocs)
1127		fmt.Fprintln(stdout)
1128		printPayment(p, s)
1129		return nil
1130	}
