1141	// sameAllocations 判定两个分配列表的月份-金额对应关系相同（顺序无关）。
1142	func sameAllocations(a, b []paymentAllocation) bool {
1143		if len(a) != len(b) {
1144			return false
1145		}
1146		for _, al := range b {
1147			if allocAmountFor(a, al.Month) != al.Amount {
1148				return false
1149			}
1150		}
1151		return true
1152	}
