1154	// formatAllocations 以 "2026-09:500,2026-10:300" 形式展示分配列表。
1155	func formatAllocations(allocs []paymentAllocation) string {
1156		parts := make([]string, len(allocs))
1157		for i, al := range allocs {
1158			parts[i] = fmt.Sprintf("%s:%d", al.Month, al.Amount)
1159		}
1160		return strings.Join(parts, ",")
1161	}
