1174	func cmdBillUnpay(dir, payID, reason string) error {
1175		if strings.TrimSpace(payID) == "" {
1176			return fmt.Errorf("收款标识不能为空")
1177		}
1178		if strings.TrimSpace(reason) == "" {
1179			return fmt.Errorf("撤销原因不能为空")
1180		}
1181	
1182		s, err := loadStore(dir)
1183		if err != nil {
1184			return err
1185		}
1186		p, ok := s.Payments[payID]
1187		if !ok {
1188			return fmt.Errorf("收款标识 %q 不存在，无法撤销", payID)
1189		}
1190	
1191		if p.Revoked {
1192			// 相同标识与相同原因重复撤销：幂等成功，不新增历史；
1193			// 改用其他原因则拒绝。
1194			if p.RevokeReason == reason {
1195				fmt.Fprintf(stdout, "收款 %q 已撤销且撤销原因相同，幂等返回（不新增历史）：\n\n", payID)
1196				printPayment(p, s)
1197				return nil
1198			}
1199			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", payID, p.RevokeReason)
1200		}
1201	
1202		// 撤销整笔生效：取消该笔在全部分配月份上的最新实收（经更正的以最新
1203		// 分配为准），不接受部分撤销；不改变应付、其他收款或调整，原收款、
1204		// 分配、更正与撤销原因永久保留。
1205		p.Revoked = true
1206		p.RevokeReason = reason
1207		p.RevokedAt = time.Now().UTC().Format(time.RFC3339)
1208		s.NextSeq++
1209		p.RevokeSeq = s.NextSeq
1210	
1211		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
1212		if err := s.save(); err != nil {
1213			p.Revoked = false
1214			p.RevokeReason = ""
1215			p.RevokedAt = ""
1216			p.RevokeSeq = 0
1217			s.NextSeq--
1218			return err
1219		}
1220		fmt.Fprintf(stdout, "已撤销收款 %q（总额 %d 分，%s），取消最新分配：\n", payID, p.Total, moneyFen(p.Total))
1221		printAllocationBalances(s, p, currentAllocations(s, p))
1222		fmt.Fprintln(stdout)
1223		printPayment(p, s)
1224		return nil
1225	}
