1241		for i, al := range p.Allocations {
1242			b := s.Bills[billKey(p.CustomerID, al.Month)] // 载入时已校验存在
1243			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, al.Month))
