1246				i+1, al.Month, al.Amount, moneyFen(al.Amount), payable, received, payable-received)
1247		}
1248		if corrs := correctionsFor(s, p.ID); len(corrs) > 0 {
1249			fmt.Fprintf(stdout, "当前分配（经 %d 次更正，以最新为准）：%s\n",
1250				len(corrs), formatAllocations(currentAllocations(s, p)))
1251		}
1252	}
