1255	
1256	func cmdBillCorrect(dir, payID, corrID, reason string, allocArgs []string) error {
1257		if strings.TrimSpace(payID) == "" {
1258			return fmt.Errorf("收款标识不能为空")
1259		}
1260		if strings.TrimSpace(corrID) == "" {
1261			return fmt.Errorf("更正标识不能为空")
1262		}
1263		if strings.TrimSpace(reason) == "" {
1264			return fmt.Errorf("更正原因不能为空")
1265		}
1266		allocs, err := parseAllocations(allocArgs)
1267		if err != nil {
1268			return err
1269		}
1270		// 分配顺序不影响更正身份：统一按月份升序保存与比较。
1271		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1272	
1273		s, err := loadStore(dir)
1274		if err != nil {
1275			return err
1276		}
1277		p, ok := s.Payments[payID]
1278		if !ok {
1279			return fmt.Errorf("收款标识 %q 不存在，无法更正分配", payID)
1280		}
1281	
1282		if existing, ok := s.Corrections[corrID]; ok {
1283			// 相同标识按目标收款、原因与新月份-金额对应关系判重（列表顺序无关）：
1284			// 内容相同返回原更正记录，不改分配、不增历史；后续更正或收款撤销
1285			// 不影响此规则。任何一项不同（含跨收款复用）均拒绝。
1286			if existing.PaymentID == payID && existing.Reason == reason && sameAllocations(existing.Allocations, allocs) {
1287				fmt.Fprintf(stdout, "更正 %q 已存在且内容相同，返回原更正记录（不改分配、不增历史）：\n\n", corrID)
1288				printCorrection(existing, s)
1289				return nil
1290			}
1291			return fmt.Errorf("更正标识 %q 已存在但内容不同（已有：收款=%s 原因=%q 新分配=%s），拒绝复用",
1292				corrID, existing.PaymentID, existing.Reason, formatAllocations(existing.Allocations))
1293		}
1294	
1295		// 新增更正只允许未撤销收款。
1296		if p.Revoked {
1297			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），不能新增分配更正", payID, p.RevokeReason)
1298		}
1299	
1300		// 新分配合计必须等于原收款总额（不重复收钱也不多收），全程整数运算。
1301		var sum int64
1302		for _, al := range allocs {
1303			sum, err = add64(sum, al.Amount)
1304			if err != nil {
1305				return fmt.Errorf("新分配金额合计溢出有符号 64 位整数范围，拒绝更正")
1306			}
1307		}
1308		if sum != p.Total {
1309			return fmt.Errorf("新分配合计 %d 分与原收款 %q 的总额 %d 分不一致，拒绝更正", sum, payID, p.Total)
1310		}
1311		// 新分配月份须是原客户的已结算账单。
1312		for _, al := range allocs {
1313			if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
1314				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），更正只能分配到已存在账单", p.CustomerID, al.Month)
1315			}
1316		}
1317	
1318		// 以当前最新分配为起点：撤去该笔当前分配再计入新分配后，涉及月份
1319		// 均须满足 0 ≤ 实收 ≤ 应付；其他收款不变，全部合法才整笔生效。
1320		current := currentAllocations(s, p)
1321		for _, m := range unionMonths(current, allocs) {
1322			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1323			_, payable, err := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1324			if err != nil {
1325				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝更正: %w", p.CustomerID, m, err)
1326			}
1327			received, err := paymentReceived(s, p.CustomerID, m)
1328			if err != nil {
1329				return fmt.Errorf("客户 %s 的 %s 实收累计异常，拒绝更正: %w", p.CustomerID, m, err)
1330			}
1331			// 该笔收款未撤销，其实收必然包含当前分配，撤去不会变负。
1332			received -= allocAmountFor(current, m)
1333			received, err = add64(received, allocAmountFor(allocs, m))
1334			if err != nil {
1335				return fmt.Errorf("客户 %s 的 %s 更正后实收溢出有符号 64 位整数范围，拒绝更正", p.CustomerID, m)
1336			}
1337			if received > payable {
1338				return fmt.Errorf("更正后客户 %s 的 %s 实收 %d 分将超过当前应付 %d 分，拒绝更正；全部状态保持不变",
1339					p.CustomerID, m, received, payable)
1340			}
1341		}
1342	
1343		c := &correction{
1344			ID:          corrID,
1345			PaymentID:   payID,
1346			Reason:      reason,
1347			Allocations: allocs,
1348			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1349		}
1350		s.NextSeq++
1351		c.Seq = s.NextSeq
1352		s.Corrections[corrID] = c
1353	
1354		// 更正记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1355		// 一切不生效，该更正标识不被占用。
1356		if err := s.save(); err != nil {
1357			delete(s.Corrections, corrID)
1358			s.NextSeq--
1359			return err
1360		}
1361		fmt.Fprintf(stdout, "已登记收款分配更正 %q（关联收款 %q）：\n\n", corrID, payID)
1362		printCorrection(c, s)
1363		return nil
1364	}
1365	
1366	// unionMonths 返回两个分配列表涉及月份的并集，按月份升序。
1367	func unionMonths(a, b []paymentAllocation) []string {
1368		set := make(map[string]bool, len(a)+len(b))
1369		for _, al := range a {
1370			set[al.Month] = true
1371		}
1372		for _, al := range b {
1373			set[al.Month] = true
1374		}
1375		months := make([]string, 0, len(set))
1376		for m := range set {
1377			months = append(months, m)
1378		}
1379		sort.Strings(months)
1380		return months
1381	}
1382	
1383	// allocationBefore 返回一次更正发生前该收款生效的分配：上一条更正的
1384	// 新分配，或（首次更正时）收款的原始分配。
1385	func allocationBefore(s *state, c *correction) []paymentAllocation {
1386		before := s.Payments[c.PaymentID].Allocations // 载入时已校验存在
1387		var latest *correction
1388		for _, o := range s.Corrections {
1389			if o.PaymentID == c.PaymentID && o.Seq < c.Seq && (latest == nil || o.Seq > latest.Seq) {
1390				latest = o
1391			}
1392		}
1393		if latest != nil {
1394			before = latest.Allocations
1395		}
1396		return before
1397	}
1398	
1399	// printCorrection 输出单笔更正记录：关联收款、标识、原因、完整前后分配，
1400	// 以及前后分配涉及月份的当前余额。
1401	func printCorrection(c *correction, s *state) {
1402		p := s.Payments[c.PaymentID] // 载入时已校验存在
1403		before := allocationBefore(s, c)
1404		fmt.Fprintf(stdout, "更正标识：%s\n", c.ID)
1405		fmt.Fprintf(stdout, "关联收款：%s（客户 %s，总额 %d 分（%s），备注：%s）\n",
1406			p.ID, p.CustomerID, p.Total, moneyFen(p.Total), p.Note)
1407		fmt.Fprintf(stdout, "原因：%s\n", c.Reason)
1408		fmt.Fprintf(stdout, "更正前分配：%s\n", formatAllocations(before))
1409		fmt.Fprintf(stdout, "更正后分配：%s\n", formatAllocations(c.Allocations))
1410		fmt.Fprintln(stdout, "涉及月份当前余额：")
1411		for _, m := range unionMonths(before, c.Allocations) {
1412			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1413			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1414			received, _ := paymentReceived(s, p.CustomerID, m)
1415			fmt.Fprintf(stdout, "  月份 %s：本笔分配 %d 分 → %d 分；当前应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1416				m, allocAmountFor(before, m), allocAmountFor(c.Allocations, m),
1417				payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1418		}
1419	}
1420	
1421	// --- 账后对账流水 ---
1422	
1423	// ledgerEvent 是某张已结算账单账后流水中的一个事件：调整、撤销调整、收款、
1424	// 分配更正或撤销收款。事件按全局操作序号升序回放；撤销在其发生序号抵消
1425	// 对应原操作，已撤销记录在撤销之前仍计入，不按当前撤销状态删除原事件；
1426	// 更正在其发生序号把关联收款在本账单的分配由前值替换为后值。
1427	type ledgerEvent struct {
1428		seq           int64  // 全局操作序号（调整/收款/更正及其撤销共用）
1429		kind          string // 事件类型：调整 / 撤销调整 / 收款 / 更正 / 撤销收款
1430		refID         string // 原记录标识（调整标识、收款标识或更正标识）
1431		deltaPayable  int64  // 对当前应付的影响（分，带符号）
1432		deltaReceived int64  // 对实收的影响（分，带符号）
1433		note          string // 原因（调整/更正类）或备注（收款类）
1434		linkSeq       int64  // 撤销事件关联的原操作序号；非撤销事件为 0
1435		payTotal      int64  // 收款类事件：汇款总额
1436		payAlloc      int64  // 收款类事件：本账单分配（撤销收款事件为被取消的最新分配）
1437		payID         string // 更正事件：关联收款标识
1438		beforeAlloc   int64  // 更正事件：本账单更正前分配
1439		afterAlloc    int64  // 更正事件：本账单更正后分配
1440		afterPayable  int64  // 事件后的应付（回放时填充）
1441		afterReceived int64  // 事件后的实收（回放时填充）
1442	}
1443	
1444	// billLedger 把目标账单的调整、调整撤销、收款、分配更正与收款撤销合并为
1445	// 一条按操作序号升序的流水，并以原总金额为初始应付、零实收为起点逐步回放，
1446	// 填充每个事件之后的三项余额。回放覆盖完整流水（不受查询截止序号限制）：
1447	// 序号重复、撤销先于原操作，或任一事件之后不满足 0 ≤ 实收 ≤ 应付 ≤ 有符号
1448	// 64 位最大值，都视为数据异常并拒绝——只检查最终余额会放过中间越界的存档。
1449	// 只读：不修改库、不占用序号、不新增记录。
1450	func billLedger(s *state, b *bill) ([]ledgerEvent, error) {
1451		var events []ledgerEvent
1452		for _, a := range s.Adjustments {
1453			if a.CustomerID != b.CustomerID || a.Month != b.Month {
1454				continue
1455			}
1456			events = append(events, ledgerEvent{
1457				seq: a.Seq, kind: "调整", refID: a.ID,
1458				deltaPayable: a.Amount, note: a.Reason,
1459			})
1460			if a.Revoked {
1461				neg, err := neg64(a.Amount)
1462				if err != nil {
1463					return nil, fmt.Errorf("调整 %q 的金额 %d 分无法抵消（越界），数据异常，拒绝输出流水", a.ID, a.Amount)
1464				}
1465				events = append(events, ledgerEvent{
1466					seq: a.RevokeSeq, kind: "撤销调整", refID: a.ID,
1467					deltaPayable: neg, note: a.RevokeReason, linkSeq: a.Seq,
1468				})
1469			}
1470		}
1471		for _, p := range s.Payments {
1472			if p.CustomerID != b.CustomerID {
1473				continue
1474			}
1475			// 多月汇款只以本账单分配改变实收；更正在其发生序号把本账单分配
1476			// 由前值替换为后值；整笔撤销在同一序号取消撤销时的最新分配。
1477			// 首次登记或任一次更正涉及本账单的，该收款的后续事件都纳入流水。
1478			alloc := p.amountFor(b.Month)
1479			corrs := correctionsFor(s, p.ID)
1480			involved := alloc > 0
1481			if !involved {
1482				for _, c := range corrs {
1483					if allocAmountFor(c.Allocations, b.Month) > 0 {
1484						involved = true
1485						break
1486					}
1487				}
1488			}
1489			if !involved {
1490				continue
1491			}
1492			if alloc > 0 {
1493				events = append(events, ledgerEvent{
1494					seq: p.Seq, kind: "收款", refID: p.ID,
1495					deltaReceived: alloc, note: p.Note,
1496					payTotal: p.Total, payAlloc: alloc,
1497				})
1498			}
1499			running := alloc
1500			for _, c := range corrs {
1501				after := allocAmountFor(c.Allocations, b.Month)
1502				if running == 0 && after == 0 {
1503					continue // 本次更正不涉及本账单
1504				}
1505				events = append(events, ledgerEvent{
1506					seq: c.Seq, kind: "更正", refID: c.ID,
1507					deltaReceived: after - running, note: c.Reason,
1508					payID: p.ID, beforeAlloc: running, afterAlloc: after,
1509				})
1510				running = after
1511			}
1512			if p.Revoked {
1513				events = append(events, ledgerEvent{
1514					seq: p.RevokeSeq, kind: "撤销收款", refID: p.ID,
1515					deltaReceived: -running, note: p.RevokeReason, linkSeq: p.Seq,
1516					payTotal: p.Total, payAlloc: running,
1517				})
1518			}
1519		}
1520		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
1521	
1522		// 逐步回放并核验：只把每个事件的金额影响加到运行余额上，不对发生额
1523		// 做累计求和，因此累计补收/收款发生额超过 64 位上限但每步余额合法时
1524		// 仍能成功。
1525		payable := b.TotalFee
1526		var received int64
1527		seen := make(map[int64]string, len(events))
1528		for i := range events {
1529			ev := &events[i]
1530			desc := ev.kind + " " + ev.refID
1531			if prev, dup := seen[ev.seq]; dup {
1532				return nil, fmt.Errorf("流水序号 %d 重复（%s 与 %s），数据异常，拒绝输出流水", ev.seq, prev, desc)
1533			}
1534			seen[ev.seq] = desc
1535			if ev.linkSeq != 0 && ev.linkSeq >= ev.seq {
1536				return nil, fmt.Errorf("%s 的撤销序号 %d 不晚于原操作序号 %d，数据异常，拒绝输出流水", desc, ev.seq, ev.linkSeq)
1537			}
1538			var err error
1539			if payable, err = addSigned64(payable, ev.deltaPayable); err != nil {
1540				return nil, fmt.Errorf("序号 %d（%s）之后应付越出有符号 64 位整数范围，数据异常，拒绝输出流水", ev.seq, desc)
1541			}
1542			if received, err = addSigned64(received, ev.deltaReceived); err != nil {
1543				return nil, fmt.Errorf("序号 %d（%s）之后实收越出有符号 64 位整数范围，数据异常，拒绝输出流水", ev.seq, desc)
1544			}
1545			if payable < 0 {
1546				return nil, fmt.Errorf("序号 %d（%s）之后应付为 %d 分（小于 0），数据异常，拒绝输出流水", ev.seq, desc, payable)
1547			}
1548			if received < 0 {
1549				return nil, fmt.Errorf("序号 %d（%s）之后实收为 %d 分（小于 0），数据异常，拒绝输出流水", ev.seq, desc, received)
1550			}
1551			if received > payable {
1552				return nil, fmt.Errorf("序号 %d（%s）之后实收 %d 分超过应付 %d 分，数据异常，拒绝输出流水", ev.seq, desc, received, payable)
1553			}
1554			ev.afterPayable = payable
1555			ev.afterReceived = received
1556		}
1557		return events, nil
1558	}
1559	
1560	func cmdBillLedger(dir, customerID, month, cutoffText string, hasCutoff bool) error {
1561		if !validMonth(month) {
1562			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
1563		}
1564		s, err := loadStore(dir)
1565		if err != nil {
1566			return err
1567		}
1568		cust, ok := s.Customers[customerID]
1569		if !ok {
1570			return fmt.Errorf("客户标识 %q 不存在", customerID)
1571		}
1572		b, ok := s.Bills[billKey(customerID, month)]
1573		if !ok {
1574			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
1575		}
1576	
1577		// 截止序号使用调整/收款及其撤销共用的已保存全局序号：省略表示最新，
1578		// 0 只返回初始余额，截止包含该序号；因其他客户或月份操作造成的序号
1579		// 空档合法。负数、非整数或超过存档全局序号上限一律拒绝。
1580		cutoff := s.NextSeq
1581		cutoffDesc := "省略，按最新"
1582		if hasCutoff {
1583			v, perr := strconv.ParseInt(strings.TrimSpace(cutoffText), 10, 64)
1584			if perr != nil {
1585				return fmt.Errorf("截止操作序号 %q 不是非负整数: %w", cutoffText, perr)
1586			}
1587			if v < 0 {
1588				return fmt.Errorf("截止操作序号不能为负数，收到 %d", v)
1589			}
1590			if v > s.NextSeq {
1591				return fmt.Errorf("截止操作序号 %d 超过存档全局序号上限 %d", v, s.NextSeq)
1592			}
1593			cutoff = v
1594			cutoffDesc = "指定"
1595		}
1596	
1597		// 先核验目标账单的完整流水：任何异常（即使发生在截止序号之后）都
1598		// 拒绝，不输出部分正常的报告。
1599		events, err := billLedger(s, b)
1600		if err != nil {
1601			return err
1602		}
1603		printBillLedger(b, cust, s.NextSeq, cutoff, cutoffDesc, events)
1604		return nil
1605	}
1606	
1607	func printBillLedger(b *bill, cust *customer, nextSeq, cutoff int64, cutoffDesc string, events []ledgerEvent) {
1608		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
1609		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
1610		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
1611		fmt.Fprintf(stdout, "原总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
1612		fmt.Fprintf(stdout, "存档全局序号上限：%d\n", nextSeq)
1613		fmt.Fprintf(stdout, "截止操作序号：%d（%s）\n", cutoff, cutoffDesc)
1614		fmt.Fprintf(stdout, "初始余额：应付 %d 分（%s），实收 0 分（%s），未收余额 %d 分（%s）\n",
1615			b.TotalFee, moneyFen(b.TotalFee), moneyFen(0), b.TotalFee, moneyFen(b.TotalFee))
1616	
1617		// 截止包含该序号；截止之后的事件（含撤销）既不出现也不影响历史余额。
1618		payable, received := b.TotalFee, int64(0)
1619		var shown []ledgerEvent
1620		for _, ev := range events {
1621			if ev.seq > cutoff {
1622				continue
1623			}
1624			shown = append(shown, ev)
1625			payable, received = ev.afterPayable, ev.afterReceived
1626		}
1627		if len(shown) == 0 {
1628			fmt.Fprintln(stdout, "流水：无（截止序号以内该账单无账后事件）")
1629		} else {
1630			fmt.Fprintln(stdout, "流水（按操作序号升序）：")
1631			for i, ev := range shown {
1632				fmt.Fprintf(stdout, "  %d. %s\n", i+1, formatLedgerEvent(ev))
1633			}
1634		}
1635		fmt.Fprintf(stdout, "截止时余额：应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1636			payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1637	}
1638	
1639	// formatLedgerEvent 渲染一条流水事件：序号、类型、原记录标识、金额影响、
1640	// 原因或备注、撤销关联，以及事件后的应付、实收、未收余额；收款类事件同时
1641	// 说明汇款总额与本账单分配。
1642	func formatLedgerEvent(ev ledgerEvent) string {
1643		after := fmt.Sprintf("事后：应付 %d 分，实收 %d 分，未收余额 %d 分",
1644			ev.afterPayable, ev.afterReceived, ev.afterPayable-ev.afterReceived)
1645		switch ev.kind {
1646		case "调整":
1647			return fmt.Sprintf("序号 %d 调整 %s：应付 %+d 分（%s，%s），原因：%s → %s",
1648				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), adjustKind(ev.deltaPayable), ev.note, after)
1649		case "撤销调整":
1650			return fmt.Sprintf("序号 %d 撤销调整 %s：应付 %+d 分（%s，关联序号 %d 的调整 %s），原因：%s → %s",
1651				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), ev.linkSeq, ev.refID, ev.note, after)
1652		case "收款":
1653			return fmt.Sprintf("序号 %d 收款 %s：实收 %+d 分（%s，汇款总额 %d 分，本账单分配 %d 分），备注：%s → %s",
1654				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payTotal, ev.payAlloc, ev.note, after)
1655		case "更正":
1656			return fmt.Sprintf("序号 %d 更正 %s：实收 %+d 分（%s，关联收款 %s，本账单分配 %d 分 → %d 分），原因：%s → %s",
1657				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payID, ev.beforeAlloc, ev.afterAlloc, ev.note, after)
1658		default: // 撤销收款
1659			return fmt.Sprintf("序号 %d 撤销收款 %s：实收 %+d 分（%s，关联序号 %d 的收款 %s，汇款总额 %d 分，取消本账单分配 %d 分），原因：%s → %s",
1660				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.linkSeq, ev.refID, ev.payTotal, ev.payAlloc, ev.note, after)
1661		}
1662	}
1663

