	// 撤回不占序号：随后的第一笔调整序号为 1。
	h.mustRun("bill", "adjust", "c1", "2026-09", "a1", "5", "补收")
	out := h.mustRun("bill", "ledger", "c1", "2026-09")
	if !strings.Contains(out, "存档全局序号上限：1") || !strings.Contains(out, "序号 1 调整 a1") {
