// --- 未封账用量撤回与按标识查询测试 ---

func TestWithdrawHappyPathAndQuery(t *testing.T) {
	h := newHarness(t)
	h.mustRun("customer", "add", "c1", "固定客户", "10")
	h.mustRun("plan", "add", "p1", "阶梯", "-:5")
