		"u1,c1,2026-09-10T08:00:00+08:00,3\n"+ // UTC 2026-09-10 00:00
		"u2,c2,2026-09-05T00:00:00Z,7\n")
	h.mustRun("usage", "import", f)

	// 固定单价客户的用量可撤回。
	out := h.mustRun("usage", "withdraw", "u1", "误导入，重复上报")
